          label: 'Elite Terminal'
        };
      case 'pro':
        return {
          bg: 'bg-gradient-to-tr from-amber-400 to-orange-500',
          shadow: 'shadow-amber-500/40',
          icon: <Zap className="w-6 h-6 text-white" />,
          label: 'Pro Uplink'
        };
      default:
        return {
          bg: 'bg-slate-800',
          shadow: 'shadow-black/20',
          icon: <Shield className="w-6 h-6 text-slate-400" />,
          label: 'Free Tier'
        };
    }
  }, [userPlan]);

  // Define Commands for Palette
  const commandList: CommandItem[] = useMemo(() => [
    { id: 'home', label: 'Go to Dashboard', group: 'Navigation', icon: <Wallet className="w-4 h-4" />, action: () => handleNavigate('dashboard') },
    { id: 'trans', label: 'Go to Transactions', group: 'Navigation', icon: <CreditCard className="w-4 h-4" />, action: () => handleNavigate('transactions') },
    { id: 'coach', label: 'Ask Financial Coach', group: 'Navigation', icon: <Sparkles className="w-4 h-4 text-indigo-400" />, action: () => handleNavigate('insights') },
    { id: 'goals', label: 'View Goals & Budgets', group: 'Navigation', icon: <Target className="w-4 h-4" />, action: () => handleNavigate('goals') },
    { id: 'smart', label: 'Open Smart Money Tools', group: 'Navigation', icon: <Cpu className="w-4 h-4" />, action: () => handleNavigate('smart_money') },
    { id: 'invest', label: 'Check Investments', group: 'Navigation', icon: <TrendingUp className="w-4 h-4" />, action: () => handleNavigate('investment') },
    { id: 'labs', label: 'Upcoming Features', group: 'Navigation', icon: <Rocket className="w-4 h-4" />, action: () => handleNavigate('upcoming') },

    { id: 'log_tx', label: 'Log New Transaction', group: 'Action', icon: <Zap className="w-4 h-4 text-amber-400" />, action: () => handleNavigate('transactions') },
    { id: 'audit', label: 'Run Neural Audit', group: 'Action', icon: <Sparkles className="w-4 h-4 text-emerald-400" />, action: () => handleNavigate('insights', { autoScan: true }) },
    { id: 'logout', label: 'Sign Out', group: 'System', icon: <LogOut className="w-4 h-4 text-rose-400" />, action: () => setIsLogoutModalOpen(true) },
