  const [activeTab, setActiveTab] = useState('dashboard');
  const [smartMoneyTab, setSmartMoneyTab] = useState('cashflow');
  const [activeReport, setActiveReport] = useState<ReportType>(null);
  const [isPrivacyMode, setIsPrivacyMode] = useState(() => localStorage.getItem('nova_privacy_mode') === 'true');
  const [isPinMode, setIsPinMode] = useState(false);
  const [autoScanTrigger, setAutoScanTrigger] = useState(false);

  const [onboardingComplete, setOnboardingComplete] = useState(() => localStorage.getItem('nova_onboarding_complete') === 'true');

  const [spendingLimit, setSpendingLimit] = useState<number>(() => {
      const stored = localStorage.getItem('nova_spending_limit');
      if (!stored) return 1000;
      const parsed = parseFloat(stored);
      return Number.isFinite(parsed) && parsed > 0 ? parsed : 1000;
  });

  const [spendingPeriod, setSpendingPeriod] = useState<SpendingPeriod>(() => (localStorage.getItem('nova_spending_period') as SpendingPeriod) || 'monthly');

  const [pinnedIds, setPinnedIds] = useState<string[]>(() => {
    try {
        const saved = localStorage.getItem('nova_pinned_ids');
        return saved ? JSON.parse(saved) : []; 
    } catch { return []; }
  });

  const [featureUsage, setFeatureUsage] = useState<Record<string, number>>(() => {
      try {
          const saved = localStorage.getItem('nova_feature_usage');
          return saved ? JSON.parse(saved) : {};
      } catch { return {}; }
  });

  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');
  const [insightUsage, setInsightUsage] = useState(() => getMonthlyUsage('nova_insight_usage'));
  const [scanUsage, setScanUsage] = useState(() => getMonthlyUsage('nova_scan_usage'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => getMonthlyUsage('nova_negotiation_usage'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [botMode, setBotMode] = useState<BotMode>(() => (localStorage.getItem('nova_bot_mode') as BotMode) || 'ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(() => parseFloat(localStorage.getItem('nova_user_avatar_zoom') || '1'));
  const [userAvatarPos, setUserAvatarPos] = useState(() => {
      try {
          const saved = localStorage.getItem('nova_user_avatar_pos');
          return saved ? JSON.parse(saved) : { x: 0, y: 0 };
      } catch { return { x: 0, y: 0 }; }
  });
  const [userBorder, setUserBorder] = useState(() => localStorage.getItem('nova_user_border') || 'default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');

  const [currency, setCurrency] = useState<Currency>(() => (localStorage.getItem('nova_currency') as Currency) || 'USD');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('nova_language') as Language) || 'en');

  useEffect(() => safeSetItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => safeSetItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => safeSetItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => safeSetItem('nova_goals', JSON.stringify(goals)), [goals]);

  useEffect(() => safeSetItem('nova_user_plan', userPlan), [userPlan]);
  useEffect(() => safeSetItem('nova_currency', currency), [currency]);
  useEffect(() => safeSetItem('nova_language', language), [language]);
  useEffect(() => safeSetItem('nova_bot_mode', botMode), [botMode]);
  useEffect(() => safeSetItem('nova_privacy_mode', isPrivacyMode.toString()), [isPrivacyMode]);
  useEffect(() => safeSetItem('nova_pinned_ids', JSON.stringify(pinnedIds)), [pinnedIds]);
  useEffect(() => safeSetItem('nova_feature_usage', JSON.stringify(featureUsage)), [featureUsage]);
  useEffect(() => safeSetItem('nova_spending_limit', spendingLimit.toString()), [spendingLimit]);
  useEffect(() => safeSetItem('nova_spending_period', spendingPeriod), [spendingPeriod]);
  useEffect(() => safeSetItem('nova_onboarding_complete', onboardingComplete.toString()), [onboardingComplete]);

  useEffect(() => { localStorage.setItem('nova_user_name', userName); }, [userName]);
  useEffect(() => { localStorage.setItem('nova_user_email', userEmail); }, [userEmail]);
  useEffect(() => { if(userAvatar) safeSetItem('nova_user_avatar', userAvatar); }, [userAvatar]);
  useEffect(() => safeSetItem('nova_user_avatar_zoom', userAvatarZoom.toString()), [userAvatarZoom]);
  useEffect(() => safeSetItem('nova_user_avatar_pos', JSON.stringify(userAvatarPos)), [userAvatarPos]);
  useEffect(() => safeSetItem('nova_user_border', userBorder), [userBorder]);
  useEffect(() => safeSetItem('nova_user_bg', userBackground), [userBackground]);

  const spendingStatus: { currentSpend: number; status: SpendingStatus } = useMemo(() => {
      const now = new Date();
      let startDate = new Date();

      if (spendingPeriod === 'weekly') {
          const day = now.getDay();
          const diff = now.getDate() - day;
          startDate = new Date(now.setDate(diff));
          startDate.setHours(0, 0, 0, 0);
      } else {
          startDate = new Date(now.getFullYear(), now.getMonth(), 1);
      }

      const currentSpend = transactions
          .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date) >= startDate)
          .reduce((acc, t) => acc + t.amount, 0);

      const status = evaluateSpending(currentSpend, spendingLimit);
      return { currentSpend, status };
  }, [transactions, spendingPeriod, spendingLimit]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: insightUsage };
      safeSetItem('nova_insight_usage', JSON.stringify(meta));
  }, [insightUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: scanUsage };
      safeSetItem('nova_scan_usage', JSON.stringify(meta));
  }, [scanUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: negotiationUsage };
      safeSetItem('nova_negotiation_usage', JSON.stringify(meta));
  }, [negotiationUsage]);

  const addToast = useCallback((message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), message, type }]);
  }, []);

  const trackFeatureUsage = useCallback((featureId: string) => {
      setFeatureUsage(prev => ({
          ...prev,
          [featureId]: (prev[featureId] || 0) + 1
      }));
  }, []);

  useEffect(() => {
      if (!isLoggedIn) return;
      const hasAutoPinned = localStorage.getItem('nova_has_auto_pinned');
      if (hasAutoPinned) return;

      const totalActions = (Object.values(featureUsage) as number[]).reduce((a, b) => a + b, 0);
      if (totalActions > 10) {
          const sorted = Object.entries(featureUsage)
              .filter(([key]) => PINNABLE_FEATURES.includes(key))
              .sort((a, b) => (b[1] as number) - (a[1] as number))
              .map(([key]) => key)
              .slice(0, 2); 

          if (sorted.length > 0) {
              setPinnedIds(sorted);
              addToast(`System optimization complete. Top ${sorted.length} modules pinned.`, 'info');
              localStorage.setItem('nova_has_auto_pinned', 'true');
          }
      }
  }, [featureUsage, isLoggedIn, addToast]);

  const handleTogglePin = (id: string) => {
    setPinnedIds(prev => {
        if (prev.includes(id)) {
            return prev.filter(p => p !== id);
        }
        const limit = userPlan === 'ultra' ? 5 : userPlan === 'pro' ? 3 : 1;
        if (prev.length >= limit) {
            addToast(`Slot Limit Reached (${limit}). Unpin a module to replace.`, 'error');
            return prev;
        }
        return [...prev, id];
    });
  };

  const handleToggleStealth = useCallback(() => {
    if (userPlan !== 'ultra') {
        addToast('Stealth Protocol is an Elite-exclusive feature.', 'info');
        setActiveTab('plans');
        return;
    }
    setIsPrivacyMode(prev => !prev);
    addToast(`Stealth Protocol ${!isPrivacyMode ? 'Engaged' : 'Disengaged'}`, 'info');
  }, [userPlan, isPrivacyMode, addToast]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        const isModI = (e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'i';
        if (isModI) {
            e.preventDefault();
            setIsPinMode(prev => {
                const newVal = !prev;
                addToast(newVal ? 'Pin Configuration Mode: ACTIVE' : 'Pin Configuration Mode: END', 'info');
                if (newVal) setActiveTab('dashboard');
                return newVal;
            });
        }
        if (e.key === 'Escape' && isPinMode) {
            setIsPinMode(false);
            addToast('Pin Configuration Mode: END', 'info');
        }
        if (e.shiftKey && e.key.toLowerCase() === 'p') {
            handleToggleStealth();
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPinMode, handleToggleStealth, addToast]);

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const formatCurrency = (amount: number) => {
    const safeAmount = isNaN(amount) ? 0 : amount;
    const val = new Intl.NumberFormat(language === 'vi' ? 'vi-VN' : 'en-US', { 
        style: 'currency', currency: currency,
    }).format(safeAmount);

    if (isPrivacyMode && userPlan === 'ultra') {
        return <span className="blur-md opacity-50 bg-white/5 px-1 rounded-md">{val.replace('-', '')}</span>;
    }
    return val;
  };

  const reconcileBalance = (tx: Transaction, direction: 'add' | 'delete') => {
      if (tx.accountId === 'manual') return;
      setAccounts(prev => prev.map(acc => {
          if (acc.id === tx.accountId) {
              const isIncome = tx.type === TransactionType.INCOME;
              let change = tx.amount;
              if (direction === 'add') change = isIncome ? change : -change;
              else change = isIncome ? -change : change;
              return { ...acc, balance: acc.balance + change };
          }
          return acc;
      }));
  };

  const handleAddTransaction = (t: Transaction) => {
      setTransactions(prev => [t, ...prev]);
      reconcileBalance(t, 'add');
      addToast('Transaction recorded.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
      const tx = transactions.find(t => t.id === id);
      if (tx) {
          reconcileBalance(tx, 'delete');
          setTransactions(prev => prev.filter(t => t.id !== id));
          addToast('Transaction purged.', 'info');
      }
  };

  const handleLogin = (name: string) => {
    setIsLoggedIn(true);
    setUserName(name);
    localStorage.setItem('nova_user_name', name);
  };

  const confirmLogout = () => {
    localStorage.removeItem('nova_auth_token');
    setIsLoggedIn(false);
    setIsLogoutModalOpen(false);
  };

  const handleAskCoach = (message?: string) => {
    if (message) {
      setPendingChatQuery(message);
    }
    setActiveTab('insights');
  };

  const handleNavigate = (tab: string, params?: any) => {
    if (params?.autoScan) setAutoScanTrigger(true);
    if (tab === 'smart_money' && params?.tab) {
        setSmartMoneyTab(params.tab);
    }

    // Logic for ReportType navigation
    if (tab !== 'insights') {
        setActiveReport(null);
    } else if (params?.reportType) {
        setActiveReport(params.reportType);
    } else if (tab === 'insights' && !params?.reportType && !pendingChatQuery) {
        // Just switching to insights without a specific report request: clear existing report? 
        // Let's clear to show the chat/scan UI by default unless navigating specifically for a report.
        setActiveReport(null);
    }

    setActiveTab(tab);
  };

  const handleOnboardingComplete = (name: string, lang: Language, per: SpendingPeriod, lim: number) => {
      const validName = name && name.trim().length > 0 ? name : 'Commander';
      setUserName(validName);
      localStorage.setItem('nova_user_name', validName);

      setLanguage(lang);
      setSpendingPeriod(per);

      const validLimit = Number.isFinite(lim) && lim > 0 ? lim : 1000;
      setSpendingLimit(validLimit);
      localStorage.setItem('nova_spending_limit', validLimit.toString());

      setOnboardingComplete(true);
      addToast(`Welcome, ${validName}. Systems online.`, 'success');
  };

  const handleExportData = () => {
    const data = {
      transactions,
      accounts,
      budgets,
      goals,
      settings: {
        userName, userEmail, userAvatar, userAvatarZoom, userAvatarPos, userBorder, userBackground,
        userPlan, currency, language, botMode, spendingLimit, spendingPeriod
      }
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `nova_backup_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    addToast('Data exported successfully.', 'success');
  };

  const handleImportData = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target?.result as string);
        if (data.transactions) setTransactions(data.transactions);
        if (data.accounts) setAccounts(data.accounts);
        if (data.budgets) setBudgets(data.budgets);
        if (data.goals) setGoals(data.goals);
        if (data.settings) {
            if (data.settings.userName) setUserName(data.settings.userName);
            if (data.settings.userEmail) setUserEmail(data.settings.userEmail);
            if (data.settings.userAvatar) setUserAvatar(data.settings.userAvatar);
            if (data.settings.userPlan) setUserPlan(data.settings.userPlan);
            if (data.settings.currency) setCurrency(data.settings.currency);
            if (data.settings.spendingLimit) setSpendingLimit(data.settings.spendingLimit);
            if (data.settings.spendingPeriod) setSpendingPeriod(data.settings.spendingPeriod);
        }
        addToast('Data imported successfully.', 'success');
      } catch (err) {
        addToast('Invalid backup file.', 'error');
      }
    };
    reader.readAsText(file);
  };

  const handleClearData = () => {
    localStorage.clear();
    window.location.reload();
  };

  const branding = useMemo(() => {
    switch (userPlan) {
      case 'ultra':
        return {
          bg: 'bg-gradient-to-tr from-indigo-600 to-purple-600',
          shadow: 'shadow-indigo-500/40',
          icon: <Sparkles className="w-6 h-6 text-white" />,
          label: 'Elite Terminal'
        };
      case 'pro':
        return {
          bg: 'bg-gradient-to-tr from-amber-400 to-orange-500',
          shadow: 'shadow-amber-500/40',
          icon: <Zap className="w-6 h-6 text-white" />,
          label: 'Pro Uplink'
        };
      default:
        return {
          bg: 'bg-slate-800',
          shadow: 'shadow-black/20',
          icon: <Shield className="w-6 h-6 text-slate-400" />,
          label: 'Free Tier'
        };
    }
  }, [userPlan]);

  if (!isLoggedIn) return <LandingPage onLoginSuccess={handleLogin} />;

  if (!onboardingComplete) return <OnboardingModal onComplete={handleOnboardingComplete} />;

  return (
    <div 
      className={`flex h-screen bg-[#020617] text-slate-100 font-sans selection:bg-indigo-500/30 overflow-hidden relative ${isPinMode ? 'cursor-default' : ''}`}
      style={userBackground ? { backgroundImage: `url(${userBackground})`, backgroundSize: 'cover', backgroundPosition: 'center' } : {}}
    >
      {userBackground && (
          <div className="absolute inset-0 bg-slate-950/50 z-0 pointer-events-none backdrop-blur-[2px]"></div>
      )}

      <FloatingAssistant transactions={transactions} budgets={budgets} userPlan={userPlan} botMode={botMode} isVisible={activeTab !== 'insights'} onOpenChat={handleAskCoach} insightUsage={insightUsage} />

      <aside className="hidden md:flex flex-col w-64 p-4 pb-8 z-20 bg-slate-950/40 backdrop-blur-md border-r border-white/5 relative">
        <div className="flex items-center gap-3 px-4 py-3 mb-8 shrink-0">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${branding.bg} ${branding.shadow}`}>{branding.icon}</div>
            <div><h1 className="text-xl font-bold tracking-tight text-white">Nova AI</h1><p className={`text-[10px] font-bold uppercase tracking-wider ${userPlan === 'ultra' ? 'text-purple-400' : userPlan === 'pro' ? 'text-amber-400' : 'text-slate-500'}`}>{branding.label}</p></div>
        </div>
        <nav className="flex-1 space-y-1 overflow-y-auto custom-scrollbar pr-1">
            {NAV_ITEMS.map((item) => {
                const isActive = activeTab === item.id;
                const label = TRANSLATIONS[language]?.[item.id as keyof typeof TRANSLATIONS['en']] || item.label;
                return (
                    <button key={item.id} onClick={() => handleNavigate(item.id)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all duration-300 group ${isActive ? 'bg-indigo-600/10 text-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.15)] ring-1 ring-indigo-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>
                        <item.icon className={`w-5 h-5 transition-colors ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-white'}`} />{label}
                    </button>
                );
            })}
        </nav>
        <div className="mt-auto pt-6 border-t border-white/5 shrink-0">
             <button onClick={handleToggleStealth} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all mb-2 ${isPrivacyMode && userPlan === 'ultra' ? 'bg-indigo-500/20 text-indigo-400 border border-indigo-500/30' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}>
                {isPrivacyMode ? <EyeOff className="w-5 h-5" /> : <Shield className="w-5 h-5" />} {isPrivacyMode ? 'Stealth Engaged' : 'Stealth Protocol'}
             </button>
             <button onClick={() => setActiveTab('settings')} className="w-full text-left px-4 py-4 rounded-2xl bg-slate-900/50 border border-white/5 flex items-center gap-3 mb-4 hover:bg-slate-800 transition-colors group">
                 <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white overflow-hidden relative border border-white/10 shadow-inner">{userAvatar ? <img src={userAvatar} className="w-full h-full object-cover" alt="User" /> : <span className="font-bold text-lg">{userName.charAt(0)}</span>}</div>
                 <div className="overflow-hidden"><h4 className="font-bold text-white text-sm truncate group-hover:text-indigo-400 transition-colors">{userName}</h4><p className="text-[10px] text-slate-500 truncate font-bold uppercase tracking-widest">{userPlan} tier</p></div>
             </button>
             <button onClick={() => setIsLogoutModalOpen(true)} className="w-full flex items-center gap-2 px-4 py-2 mb-4 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors uppercase tracking-widest"><LogOut className="w-4 h-4" /> Sign Out</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        {isPinMode && (
          <div className="absolute inset-0 z-[100] bg-black/40 backdrop-blur-[2px] pointer-events-none flex flex-col items-center justify-start pt-20">
              <div className="bg-indigo-600/90 text-white font-black text-xs uppercase tracking-[0.3em] px-8 py-4 rounded-2xl shadow-[0_0_50px_rgba(99,102,241,0.5)] border border-indigo-400/50 animate-pulse pointer-events-auto">
                  Pin Mode Active :: Select Priority Nodes :: Esc to Exit
              </div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
            {activeTab === 'dashboard' && <Dashboard userName={userName} accounts={accounts} transactions={transactions} goals={goals} budgets={budgets} onNavigate={handleNavigate} onAddAccount={() => setActiveTab('accounts')} onAddTransaction={() => setActiveTab('transactions')} onAddGoal={() => setActiveTab('goals')} formatCurrency={formatCurrency} userPlan={userPlan} onAskCoach={handleAskCoach} isPinMode={isPinMode} pinnedIds={pinnedIds} onTogglePin={handleTogglePin} trackEvent={trackFeatureUsage} insightUsage={insightUsage} spendingStatus={spendingStatus.status} currentPeriodSpend={spendingStatus.currentSpend} spendingLimit={spendingLimit} spendingPeriod={spendingPeriod} />}
            {activeTab === 'transactions' && <Transactions transactions={transactions} accounts={accounts} onDelete={handleDeleteTransaction} onAdd={handleAddTransaction} formatCurrency={formatCurrency} onNavigateToAccounts={() => setActiveTab('accounts')} userPlan={userPlan} scanUsage={scanUsage} onIncrementScan={() => setScanUsage(prev => prev + 1)} currency={currency} />}
            {activeTab === 'accounts' && <Accounts accounts={accounts} budgets={budgets} transactions={transactions} userPlan={userPlan} onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account linked.', 'success'); }} onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated.', 'success'); }} onDelete={(id) => { setAccounts(prev => prev.filter(a => a.id !== id)); setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t)); addToast('Account removed.', 'info'); }} formatCurrency={formatCurrency} userName={userName} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} onNavigate={handleNavigate} />}

            {activeTab === 'smart_money' && (
                <SmartMoney 
                    initialTab={smartMoneyTab}
                    transactions={transactions} 
                    accounts={accounts} 
                    goals={goals} 
                    formatCurrency={formatCurrency} 
                    userPlan={userPlan} 
                    onUpgradeClick={() => setActiveTab('plans')} 
                    insightUsage={insightUsage} 
                    onIncrementUsage={(amount) => setInsightUsage(prev => prev + (amount || 1))} 
                    negotiationUsage={negotiationUsage}
                    onIncrementNegotiationUsage={() => setNegotiationUsage(prev => prev + 1)}
                />
            )}

            {activeTab === 'insights' && <Insights transactions={transactions} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} formatCurrency={formatCurrency} insightUsage={insightUsage} onIncrementUsage={() => setInsightUsage(prev => prev + 1)} onApplyBudgets={(newBudgets) => { const existingCats = new Set(budgets.map(b => b.category)); const toAdd = newBudgets.filter(b => !existingCats.has(b.category)); setBudgets(prev => [...prev, ...toAdd]); addToast(`Applied ${toAdd.length} AI limits.`, 'success'); }} initialPrompt={pendingChatQuery} onPromptHandled={() => setPendingChatQuery(null)} botMode={botMode} onNavigate={handleNavigate} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal created from proposal.', 'success'); }} goals={goals} budgets={budgets} autoScanTriggered={autoScanTrigger} activeReport={activeReport} spendingLimit={spendingLimit} />}
            {activeTab === 'goals' && <Goals goals={goals} budgets={budgets} transactions={transactions} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal deployed.', 'success'); }} onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated.', 'success'); }} onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Limit set.', 'success'); }} onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Limit removed.', 'info'); }} formatCurrency={formatCurrency} />}
            {activeTab === 'plans' && <Plans currentPlan={userPlan} onUpgrade={(plan) => { setUserPlan(plan); addToast(`Plan upgraded.`, 'success'); }} onDowngrade={() => { setUserPlan('free'); addToast('Plan reset.', 'info'); }} onNavigateDashboard={() => setActiveTab('dashboard')} />}
            {activeTab === 'investment' && <Investment accounts={accounts} formatCurrency={formatCurrency} userPlan={userPlan} />}
            {activeTab === 'upcoming' && <UpcomingFeatures />}
            {activeTab === 'settings' && <Settings userName={userName} userEmail={userEmail} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} userBackground={userBackground} onUpdateBackground={setUserBackground} userPlan={userPlan} onUpdateProfile={(n, e, a, z, p, b) => { 
                // Immediate manual save to ensure persistence
                localStorage.setItem('nova_user_name', n);
                localStorage.setItem('nova_user_email', e);
                if (a) localStorage.setItem('nova_user_avatar', a);

                setUserName(n); 
                setUserEmail(e); 
                setUserAvatar(a); 
                setUserAvatarZoom(z); 
                setUserAvatarPos(p); 
                setUserBorder(b); 
                addToast('Profile updated.', 'success'); 
            }} addToast={addToast} onExportData={handleExportData} onImportData={handleImportData} onClearData={handleClearData} language={language} onUpdateLanguage={setLanguage} currency={currency} onUpdateCurrency={setCurrency} botMode={botMode} onUpdateBotMode={setBotMode} spendingLimit={spendingLimit} onUpdateSpendingLimit={setSpendingLimit} spendingPeriod={spendingPeriod} onUpdateSpendingPeriod={setSpendingPeriod} />}
        </div>
      </main>

      {isLogoutModalOpen && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-2xl animate-fade-in">
              <div className="bg-[#0f172a] border border-rose-500/30 rounded-[3rem] w-full max-w-sm shadow-[0_0_100px_rgba(244,63,94,0.2)] p-10 text-center animate-slide-up relative">
                  <div className="w-20 h-20 bg-rose-500/20 rounded-[2rem] flex items-center justify-center mx-auto mb-8 border border-rose-500/30"><ShieldX className="w-10 h-10 text-rose-500" /></div>
                  <h3 className="text-2xl font-black text-white mb-3 uppercase tracking-tighter">Terminate?</h3>
                  <div className="space-y-4">
                      <button onClick={confirmLogout} className="w-full py-4 bg-rose-600 hover:bg-rose-500 text-white font-black rounded-2xl shadow-xl transition-all">Sign Out</button>
                      <button onClick={() => setIsLogoutModalOpen(false)} className="w-full py-4 bg-slate-900/50 text-slate-400 font-bold rounded-2xl border border-white/5 hover:text-white transition-all">Stay Connected</button>
                  </div>
              </div>
          </div>
      )}

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Transaction, AIAnalysisResponse, ChatMessage, UserPlan, TransactionType, Budget, BotMode, Category, Goal, FinancialSnapshot, SuggestedAction, GoalProposal, DailyReport, MonthlyReport, ReportType } from '../types';
import { analyzeFinancialData, chatWithFinancialCoach } from '../services/geminiService';
import { generateDailyReport, generateMonthlyReport } from '../services/reportEngine';
import { RefreshCcw, CheckCircle, AlertTriangle, ShieldAlert, Info, TrendingUp, Bot, User, BrainCircuit, Lightbulb, Send, Lock, Sparkles, RefreshCw, Flame, ArrowRight, Zap, Crown, TrendingDown, ShoppingCart, Wallet, Terminal, Activity, MousePointerClick, ChevronRight, Check, X, EyeOff, Target, MessageSquare, AlertOctagon, Calendar, ChevronDown } from 'lucide-react';

interface InsightsProps {
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  initialPrompt?: string | null; 
  onPromptHandled?: () => void; 
  onApplyBudgets?: (budgets: Budget[]) => void; 
  insightUsage: number; 
  onIncrementUsage: () => void; 
  botMode: BotMode;
  onNavigate: (tab: string) => void;
  onAddGoal?: (goal: Goal) => void;
  autoScanTriggered?: boolean;
  activeReport?: ReportType;
  spendingLimit?: number;
}

const getIconForType = (type: string) => {
  switch (type) {
    case 'success': return <CheckCircle className="w-5 h-5 text-emerald-400" />;
    case 'warning': return <AlertTriangle className="w-5 h-5 text-amber-400" />;
    case 'critical': return <ShieldAlert className="w-5 h-5 text-rose-400" />;
    default: return <Info className="w-5 h-5 text-blue-400" />;
  }
};

const getColorClass = (type: string) => {
  switch (type) {
    case 'success': return 'bg-emerald-500/10 border-emerald-500/20 text-emerald-100';
    case 'warning': return 'bg-amber-500/10 border-amber-500/20 text-amber-100';
    case 'critical': return 'bg-rose-500/10 border-rose-500/20 text-rose-100';
    default: return 'bg-blue-500/10 border-blue-500/20 text-blue-100';
  }
};

const Insights: React.FC<InsightsProps> = ({ 
    transactions, 
    goals, 
    budgets, 
    userPlan, 
    onUpgradeClick, 
    formatCurrency, 
    initialPrompt, 
    onPromptHandled, 
    onApplyBudgets, 
    insightUsage, 
    onIncrementUsage, 
    botMode, 
    onNavigate, 
    onAddGoal,
    autoScanTriggered = false,
    activeReport,
    spendingLimit = 1000
}) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { 
        id: '1', 
        role: 'assistant', 
        content: botMode === 'ruthless' 
            ? 'System initialized. Ready to audit your spending vectors.' 
            : 'Hello! I\'m ready to help you optimize your financial wellness. What\'s on your mind?', 
        timestamp: new Date(),
        sentiment: 'info'
    }
  ]);
  const [chatLoading, setChatLoading] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState<GoalProposal | null>(null);
  const [rejectionReason, setRejectionReason] = useState('');

  // Dedicated Report State
  const [dailyReport, setDailyReport] = useState<DailyReport | null>(null);
  const [monthlyReport, setMonthlyReport] = useState<MonthlyReport | null>(null);
  const [showScanMenu, setShowScanMenu] = useState(false);

  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isPro = userPlan === 'pro';
  const currentLimit = isUltra ? 1500 : isPro ? 50 : 3;
  const isLocked = insightUsage >= currentLimit;

  // Handle activeReport trigger
  useEffect(() => {
      if (activeReport === 'daily') {
          handleGenerateDaily();
      } else if (activeReport === 'monthly') {
          handleGenerateMonthly();
      } else {
          // If null, we might want to clear reports to show chat, or keep last state?
          // Let's clear to allow returning to dashboard/chat flow
          setDailyReport(null);
          setMonthlyReport(null);
      }
  }, [activeReport, transactions, spendingLimit]);

  const handleGenerateDaily = () => {
      const report = generateDailyReport(transactions, spendingLimit || 1000);
      setDailyReport(report);
      setMonthlyReport(null);
      setShowScanMenu(false);
  };

  const handleGenerateMonthly = () => {
      const report = generateMonthlyReport(transactions, spendingLimit || 1000);
      setMonthlyReport(report);
      setDailyReport(null);
      setShowScanMenu(false);
  };

  const handleRunAI = () => {
      runAnalysis();
      setShowScanMenu(false);
  };

  const runAnalysis = async () => {
    if (isLocked || loading) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    // Clear other reports when AI runs to show the Neural Audit results
    setDailyReport(null);
    setMonthlyReport(null);

    try {
      const result = await analyzeFinancialData(transactions, userPlan);
      if (result) setAnalysis(result);
      else setError("Coach is analyzing other portfolios. Try again.");
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (autoScanTriggered && !analysis && !loading && !isLocked) {
        runAnalysis();
    }
  }, [autoScanTriggered, analysis, loading, isLocked]);

  const handleAcceptProposal = (proposal: GoalProposal) => {
      if (proposal.type === 'goal' && onAddGoal) {
          onAddGoal({
              id: Date.now().toString(),
              name: proposal.title,
              targetAmount: proposal.target_amount,
              currentAmount: 0,
              deadline: proposal.deadline || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
              icon: 'star',
              color: 'from-emerald-500 to-teal-500'
          });
      } else if (proposal.type === 'budget' && onApplyBudgets) {
          onApplyBudgets([{
              id: `ai_${Date.now()}`,
              category: (proposal.category as Category) || Category.OTHER,
              limit: proposal.target_amount,
              startDate: new Date().toISOString()
          }]);
      }
      if (analysis) setAnalysis({ ...analysis, goal_proposals: analysis.goal_proposals.filter(p => p.id !== proposal.id) });
  };

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    const now = new Date();
    const currentMonthTxs = transactions.filter(t => new Date(t.date).getMonth() === now.getMonth());
    const income = currentMonthTxs.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const expense = currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

    const catMap: Record<string, number> = {};
    currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const topCat = Object.entries(catMap).sort((a,b) => b[1] - a[1])[0];

    const snapshot: FinancialSnapshot = {
        currentMonthMetrics: {
            income,
            expense,
            savingsRate: income > 0 ? (income - expense) / income : 0,
            topExpenseCategory: topCat ? topCat[0] : 'None'
        },
        recentTransactions: transactions.slice(0, 10),
        activeGoals: goals,
        budgets: budgets
    };

    const response = await chatWithFinancialCoach(userMsg.content, chatHistory, snapshot, botMode, userPlan);
    setChatHistory(prev => [...prev, { 
        id: (Date.now() + 1).toString(), 
        role: 'assistant', 
        content: response.message, 
        timestamp: new Date(),
        sentiment: response.sentiment as any,
        suggestedActions: response.suggestedActions
    }]);
    setChatLoading(false);
  };

  const handleActionClick = (action: SuggestedAction) => {
    if (action.actionId.startsWith('navigate_')) {
        const tab = action.actionId.replace('navigate_', '');
        onNavigate(tab);
    } else if (action.actionId === 'chat_prompt' && action.payload) {
        handleSendMessage(null, action.payload);
    }
  };

  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatHistory, chatLoading]);

  // Daily Report UI
  if (dailyReport) {
      return (
          <div className="h-[calc(100vh-8rem)] flex flex-col items-center justify-center p-4">
              <div className="w-full max-w-2xl bg-slate-950 border border-white/10 rounded-[3rem] p-8 shadow-2xl relative overflow-hidden animate-slide-up">
                  <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/10 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>

                  <div className="flex justify-between items-start mb-8 relative z-10">
                      <div>
                          <div className="flex items-center gap-3 mb-2">
                              <div className="p-2 bg-indigo-600 rounded-xl shadow-lg"><Zap className="w-6 h-6 text-white" /></div>
                              <h2 className="text-2xl font-black text-white uppercase tracking-tighter">Daily Summary</h2>
                          </div>
                          <p className="text-slate-400 text-sm font-medium">{new Date(dailyReport.date).toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
                      </div>
                      <button onClick={() => setDailyReport(null)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X className="w-5 h-5 text-slate-500" /></button>
                  </div>

                  <div className="grid grid-cols-2 gap-6 mb-8">
                      <div className="p-5 bg-slate-900/50 rounded-3xl border border-white/5">
                          <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Risk Level</div>
                          <div className={`text-2xl font-black ${dailyReport.riskLevel === 'Critical' ? 'text-rose-500' : dailyReport.riskLevel === 'Warning' ? 'text-amber-400' : 'text-emerald-400'}`}>
                              {dailyReport.riskLevel} <span className="text-sm text-slate-600 font-bold">({dailyReport.riskScore.toFixed(0)}/100)</span>
                          </div>
                      </div>
                      <div className="p-5 bg-slate-900/50 rounded-3xl border border-white/5">
                          <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Today Spend</div>
                          <div className="text-2xl font-black text-white">
                              {formatCurrency(dailyReport.totals.expense)} <span className="text-sm text-slate-600 font-bold">/ {formatCurrency(dailyReport.totals.budget)}</span>
                          </div>
                      </div>
                  </div>

                  <div className="space-y-4 mb-8">
                      <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest px-1">Detected Signals</h3>
                      {dailyReport.signals.map((sig, idx) => (
                          <div key={idx} className="flex items-start gap-4 p-4 bg-slate-900/30 rounded-2xl border border-white/5 hover:bg-slate-900/50 transition-colors">
                              <div className={`mt-1 p-1.5 rounded-lg ${sig.type === 'stable' ? 'bg-emerald-500/10 text-emerald-400' : 'bg-rose-500/10 text-rose-400'}`}>
                                  {sig.type === 'stable' ? <CheckCircle className="w-4 h-4" /> : <AlertOctagon className="w-4 h-4" />}
                              </div>
                              <div>
                                  <h4 className="text-sm font-bold text-white">{sig.title}</h4>
                                  <p className="text-xs text-slate-400 mt-0.5">{sig.description}</p>
                              </div>
                          </div>
                      ))}
                  </div>

                  <div className={`p-6 rounded-3xl border flex items-start gap-4 ${dailyReport.action.priority === 'high' ? 'bg-rose-950/30 border-rose-500/30' : 'bg-indigo-950/30 border-indigo-500/30'}`}>
                      <div className={`p-2 rounded-xl shrink-0 ${dailyReport.action.priority === 'high' ? 'bg-rose-500 text-white' : 'bg-indigo-500 text-white'}`}>
                          <Target className="w-5 h-5" />
                      </div>
                      <div>
                          <div className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Recommended Action</div>
                          <h4 className="text-lg font-bold text-white mb-2">{dailyReport.action.text}</h4>
                          <div className="flex items-center gap-2 text-xs font-medium opacity-80">
                              <TrendingUp className="w-3 h-3" /> Effect: {dailyReport.action.effect}
                          </div>
                      </div>
                  </div>
              </div>
          </div>
      );
  }

  // Monthly Report UI
  if (monthlyReport) {
      return (
          <div className="h-[calc(100vh-8rem)] flex flex-col items-center justify-center p-4">
              <div className="w-full max-w-3xl bg-slate-950 border border-white/10 rounded-[3rem] p-8 shadow-2xl relative overflow-hidden animate-slide-up flex flex-col max-h-full overflow-y-auto custom-scrollbar">
                  <div className="absolute top-0 left-0 w-96 h-96 bg-emerald-500/5 rounded-full blur-3xl -ml-20 -mt-20 pointer-events-none"></div>

                  <div className="flex justify-between items-center mb-8 relative z-10 shrink-0">
                      <div className="flex items-center gap-4">
                          <div className="w-12 h-12 rounded-2xl bg-slate-900 border border-white/10 flex items-center justify-center shadow-xl">
                              <Calendar className="w-6 h-6 text-emerald-400" />
                          </div>
                          <div>
                              <h2 className="text-2xl font-black text-white uppercase tracking-tighter">Monthly Strategic</h2>
                              <p className="text-slate-400 text-sm font-medium">{monthlyReport.month}</p>
                          </div>
                      </div>
                      <button onClick={() => setMonthlyReport(null)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X className="w-5 h-5 text-slate-500" /></button>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-10 shrink-0">
                      <div className="p-6 bg-slate-900/50 rounded-[2rem] border border-white/5 flex flex-col justify-center items-center text-center">
                          <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Health Score</div>
                          <div className={`text-4xl font-black ${monthlyReport.healthScore >= 80 ? 'text-emerald-400' : 'text-amber-400'}`}>
                              {monthlyReport.healthScore.toFixed(0)}
                          </div>
                          <div className="mt-2 px-3 py-1 bg-white/5 rounded-full text-[10px] font-bold uppercase tracking-wider text-slate-300 border border-white/5">
                              {monthlyReport.healthLevel}
                          </div>
                      </div>
                      <div className="p-6 bg-slate-900/50 rounded-[2rem] border border-white/5 flex flex-col justify-center items-center text-center">
                          <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Savings Rate</div>
                          <div className="text-3xl font-black text-white">
                              {(monthlyReport.metrics.savingsPowerIndex * 100).toFixed(1)}%
                          </div>
                          <div className="text-xs text-slate-500 mt-1 font-medium">of Income</div>
                      </div>
                      <div className="p-6 bg-slate-900/50 rounded-[2rem] border border-white/5 flex flex-col justify-center items-center text-center">
                          <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Risk Factor</div>
                          <div className={`text-3xl font-black ${monthlyReport.riskScore > 50 ? 'text-rose-500' : 'text-emerald-400'}`}>
                              {monthlyReport.riskScore.toFixed(0)}
                          </div>
                          <div className="text-xs text-slate-500 mt-1 font-medium">Volatility</div>
                      </div>
                  </div>

                  <div className="space-y-8">
                      <div>
                          <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4 px-2">Structural Diagnosis</h3>
                          <div className="space-y-3">
                              {monthlyReport.problems.map((prob, idx) => (
                                  <div key={idx} className="flex items-center gap-4 p-4 rounded-2xl bg-slate-900/30 border border-white/5">
                                      <div className={`w-2 h-2 rounded-full shrink-0 ${prob.severity === 'high' ? 'bg-rose-500 shadow-[0_0_8px_#f43f5e]' : prob.severity === 'medium' ? 'bg-amber-500' : 'bg-emerald-500'}`}></div>
                                      <span className="text-sm font-bold text-slate-200">{prob.title}</span>
                                  </div>
                              ))}
                          </div>
                      </div>

                      <div className="bg-gradient-to-br from-indigo-900/20 to-violet-900/10 p-8 rounded-[2.5rem] border border-indigo-500/20 relative overflow-hidden">
                          <div className="absolute top-0 right-0 p-6 opacity-20"><Crown className="w-12 h-12 text-indigo-400" /></div>
                          <h3 className="text-lg font-black text-white mb-6 flex items-center gap-2 relative z-10"><Sparkles className="w-5 h-5 text-indigo-400" /> Strategic Plan</h3>

                          <div className="space-y-6 relative z-10">
                              <div>
                                  <div className="text-[10px] font-black text-indigo-300 uppercase tracking-widest mb-1">Primary Objective</div>
                                  <div className="text-xl font-bold text-white">{monthlyReport.strategicPlan.objective}</div>
                              </div>

                              <div className="space-y-3">
                                  {monthlyReport.strategicPlan.actions.map((action, i) => (
                                      <div key={i} className="flex items-center gap-3">
                                          <div className="w-5 h-5 rounded-full bg-indigo-500 flex items-center justify-center text-[10px] font-bold text-white shrink-0">{i + 1}</div>
                                          <p className="text-sm font-medium text-slate-300">{action}</p>
                                      </div>
                                  ))}
                              </div>

                              <div className="pt-6 border-t border-indigo-500/20 flex items-center gap-2">
                                  <TrendingUp className="w-4 h-4 text-emerald-400" />
                                  <span className="text-xs font-bold text-emerald-300">Projected Outcome: {monthlyReport.strategicPlan.outcome}</span>
                              </div>
                          </div>
                      </div>
                  </div>
              </div>
          </div>
      );
  }

  // Default Chat View
  return (
    <div className="relative h-[calc(100vh-8rem)]">
      {isLocked && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-950/60 backdrop-blur-xl rounded-[2rem] border border-white/10 transform scale-105 transition-transform duration-500">
            <div className="text-center p-8 max-w-md animate-slide-up">
                <div className="w-20 h-20 rounded-3xl bg-gradient-to-tr from-indigo-500 to-purple-500 flex items-center justify-center mx-auto mb-6 shadow-2xl shadow-indigo-500/40"><Lock className="w-10 h-10 text-white" /></div>
                <h2 className="text-3xl font-bold text-white mb-3">Limit Reached</h2>
                <p className="text-slate-400 mb-8 leading-relaxed">Cap of {currentLimit} interactions hit. Upgrade to continue.</p>
                <button onClick={onUpgradeClick} className="w-full py-4 bg-white text-indigo-900 font-bold rounded-xl shadow-xl hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2 group">Upgrade Plan</button>
            </div>
        </div>
      )}
      <div className={`grid grid-cols-1 lg:grid-cols-12 gap-8 pb-10 h-full transition-all duration-500 ${isLocked ? 'blur-md opacity-50 pointer-events-none select-none overflow-hidden' : ''}`}>

        {/* LEFT COLUMN: ANALYSIS REPORT */}
        <div className="lg:col-span-7 overflow-y-auto custom-scrollbar space-y-8 pr-2">

            <div className="flex items-center justify-between mb-2">
                <div>
                    <h2 className="text-2xl font-black text-white flex items-center gap-3 tracking-tight"><BrainCircuit className="w-8 h-8 text-indigo-400" />Neural Audit</h2>
                    <p className="text-slate-400 text-xs mt-1 font-bold uppercase tracking-widest">System Analysis & Strategic Insights</p>
                </div>
                <div className="flex items-center gap-4 relative">
                    <div className={`inline-flex items-center gap-2 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border ${isUltra ? 'bg-indigo-500/10 border-indigo-500/20 text-indigo-400' : isPro ? 'bg-amber-500/10 border-amber-500/20 text-amber-400' : 'bg-slate-700/50 border-white/10 text-slate-400'}`}>Tokens: {insightUsage}/{currentLimit}</div>

                    <div className="relative">
                        <button 
                            onClick={() => setShowScanMenu(!showScanMenu)} 
                            disabled={loading} 
                            className="px-6 py-3 bg-white text-indigo-950 rounded-xl font-black text-xs uppercase tracking-widest shadow-lg hover:scale-105 active:scale-95 transition-all flex items-center gap-2 disabled:opacity-50"
                        >
                            {loading ? <RefreshCw className="w-4 h-4 animate-spin" /> : <RefreshCcw className="w-4 h-4" />} 
                            Initialize Scan <ChevronDown className={`w-3 h-3 transition-transform ${showScanMenu ? 'rotate-180' : ''}`} />
                        </button>

                        {showScanMenu && (
                            <div className="absolute right-0 top-full mt-2 w-56 bg-slate-900 border border-white/10 rounded-2xl shadow-2xl overflow-hidden z-50 animate-fade-in flex flex-col p-1">
                                <button onClick={handleRunAI} className="flex items-center gap-3 px-4 py-3 hover:bg-white/5 rounded-xl text-left transition-colors group">
                                    <div className="p-1.5 bg-indigo-500/20 rounded-lg text-indigo-400 group-hover:text-white group-hover:bg-indigo-500 transition-colors"><BrainCircuit className="w-4 h-4" /></div>
                                    <div>
                                        <span className="block text-[10px] font-black text-white uppercase tracking-wider">Neural Audit</span>
                                        <span className="block text-[9px] text-slate-500">AI Deep Analysis</span>
                                    </div>
                                </button>
                                <button onClick={handleGenerateDaily} className="flex items-center gap-3 px-4 py-3 hover:bg-white/5 rounded-xl text-left transition-colors group">
                                    <div className="p-1.5 bg-emerald-500/20 rounded-lg text-emerald-400 group-hover:text-white group-hover:bg-emerald-500 transition-colors"><Zap className="w-4 h-4" /></div>
                                    <div>
                                        <span className="block text-[10px] font-black text-white uppercase tracking-wider">Daily Tactical</span>
                                        <span className="block text-[9px] text-slate-500">24h Risk Check</span>
                                    </div>
                                </button>
                                <button onClick={handleGenerateMonthly} className="flex items-center gap-3 px-4 py-3 hover:bg-white/5 rounded-xl text-left transition-colors group">
                                    <div className="p-1.5 bg-amber-500/20 rounded-lg text-amber-400 group-hover:text-white group-hover:bg-amber-500 transition-colors"><Calendar className="w-4 h-4" /></div>
                                    <div>
                                        <span className="block text-[10px] font-black text-white uppercase tracking-wider">Monthly Report</span>
                                        <span className="block text-[9px] text-slate-500">Strategic Health</span>
                                    </div>
                                </button>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {loading && (
                <div className="flex flex-col items-center justify-center py-32 space-y-6">
                    <Activity className="w-16 h-16 text-indigo-500 animate-bounce" />
                    <p className="text-slate-400 text-sm font-bold uppercase tracking-[0.3em] animate-pulse">Processing Neural Vectors...</p>
                </div>
            )}

            {!analysis && !loading && (
                <div className="flex flex-col items-center justify-center py-20 text-center border-2 border-dashed border-slate-800 rounded-[3rem] bg-slate-900/20">
                    <div className="w-24 h-24 bg-slate-900 rounded-full flex items-center justify-center mb-6 shadow-xl"><BrainCircuit className="w-10 h-10 text-slate-600" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">System Idle</h3>
                    <p className="text-slate-500 max-w-sm text-sm">Initiate a scan to generate a comprehensive risk audit.</p>
                </div>
            )}

            {analysis && !loading && (
            <div className="animate-fade-in space-y-8">
                <div className="grid grid-cols-2 gap-6">
                    <div className="glass-card p-6 rounded-3xl relative overflow-hidden group border-indigo-500/10 bg-gradient-to-br from-slate-900 to-indigo-950/20">
                        <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">System Health</h3>
                        <div className="flex items-end justify-between">
                            <div className="flex-1 min-w-0"><h4 className={`text-3xl font-black ${analysis.risk_score > 50 ? 'text-rose-400' : 'text-emerald-400'} tracking-tighter`}>{analysis.risk_score > 50 ? 'CRITICAL' : 'STABLE'}</h4><p className="text-xs text-slate-500 font-medium mt-1">Risk Score: {Math.round(analysis.risk_score)}/100</p></div>
                            <div className={`w-12 h-12 rounded-xl flex items-center justify-center shadow-lg ${analysis.risk_score > 50 ? 'bg-rose-500/20 text-rose-400' : 'bg-emerald-500/20 text-emerald-400'}`}><ShieldAlert className="w-6 h-6" /></div>
                        </div>
                    </div>
                    <div className="glass-card p-6 rounded-3xl relative overflow-hidden border-indigo-500/10 bg-gradient-to-br from-slate-900 to-indigo-950/20">
                         <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Predicted Burn (30d)</h3>
                         <div className="flex items-end justify-between">
                             <div><div className="text-3xl font-black text-white tracking-tighter">{formatCurrency(analysis.predicted_spend_next_month)}</div><p className="text-xs text-slate-500 font-medium mt-1">AI Projection</p></div>
                             <div className="w-12 h-12 rounded-xl bg-indigo-500/20 text-indigo-400 flex items-center justify-center shadow-lg"><TrendingUp className="w-6 h-6" /></div>
                         </div>
                    </div>
                </div>

                <div>
                    <h3 className="text-sm font-black text-slate-500 uppercase tracking-widest mb-4 flex items-center gap-2"><Lightbulb className="w-4 h-4 text-amber-400" />Strategic Intelligence</h3>
                    <div className="grid grid-cols-1 gap-4">
                        {analysis.insights.map((insight, idx) => (
                            <div key={idx} className={`p-5 rounded-2xl border flex gap-4 backdrop-blur-md transition-all hover:translate-x-1 ${getColorClass(insight.type)}`}>
                                <div className="mt-0.5 shrink-0">{getIconForType(insight.type)}</div>
                                <div><h4 className="font-bold text-sm mb-1">{insight.title}</h4><p className="text-xs opacity-90 leading-relaxed font-medium">{insight.description}</p></div>
                            </div>
                        ))}
                    </div>
                </div>

                {analysis.goal_proposals && analysis.goal_proposals.length > 0 && (
                    <div className="bg-gradient-to-br from-indigo-900/20 to-purple-900/10 p-6 rounded-[2.5rem] border border-indigo-500/20">
                        <div className="flex justify-between items-center mb-6"><h3 className="text-lg font-bold text-white flex items-center gap-2"><Sparkles className="w-5 h-5 text-indigo-400" />Strategic Proposal</h3><span className="text-[10px] font-black text-indigo-400 bg-indigo-500/10 px-2 py-1 rounded uppercase tracking-widest">High Impact</span></div>
                        <div className="space-y-4">
                            {analysis.goal_proposals.map((proposal) => (
                                <div key={proposal.id} className="bg-slate-950/60 p-5 rounded-2xl border border-white/5 relative overflow-hidden group hover:border-indigo-500/30 transition-all">
                                    <div className="flex justify-between items-start mb-4 relative z-10"><div className="flex items-center gap-3"><div className="w-10 h-10 rounded-xl bg-indigo-500/20 flex items-center justify-center border border-indigo-500/30">{proposal.type === 'goal' ? <Target className="w-5 h-5 text-indigo-400" /> : <ShieldAlert className="w-5 h-5 text-indigo-400" />}</div><div><h4 className="font-bold text-white text-base">{proposal.title}</h4><p className="text-[10px] text-slate-400 uppercase tracking-wider">{proposal.type === 'goal' ? 'New Target' : 'Budget Fix'}</p></div></div><div className="text-right"><div className="font-black text-white text-lg">{formatCurrency(proposal.target_amount)}</div></div></div>
                                    <p className="text-sm text-slate-300 mb-4 leading-relaxed font-medium relative z-10">{proposal.reason_simple}</p>
                                    <div className="flex gap-3 relative z-10"><button onClick={() => setShowRejectModal(proposal)} className="flex-1 py-3 bg-slate-800 hover:bg-slate-700 text-slate-400 font-bold text-xs uppercase tracking-widest rounded-xl transition-all">Dismiss</button><button onClick={() => handleAcceptProposal(proposal)} className="flex-[2] py-3 bg-indigo-600 hover:bg-indigo-500 text-white font-bold text-xs uppercase tracking-widest rounded-xl shadow-lg transition-all flex items-center justify-center gap-2"><Check className="w-4 h-4" /> Accept</button></div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>
            )}
        </div>

        {/* RIGHT COLUMN: CHAT INTERFACE */}
        <div className="lg:col-span-5 h-[600px] lg:h-auto flex flex-col bg-slate-900/60 rounded-[2.5rem] border border-white/10 shadow-2xl relative overflow-hidden">
            <div className="p-6 border-b border-white/5 bg-slate-950/80 backdrop-blur-xl z-10 flex justify-between items-center">
                <div className="flex items-center gap-3">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${botMode === 'ruthless' ? 'bg-slate-800' : 'bg-gradient-to-tr from-indigo-500 to-purple-500'}`}>{botMode === 'ruthless' ? <Terminal className="w-5 h-5 text-slate-300" /> : <Bot className="w-5 h-5 text-white" />}</div>
                    <div><h3 className="font-bold text-white text-sm">Financial Agent</h3><div className="flex items-center gap-1.5 mt-0.5"><div className={`w-1.5 h-1.5 rounded-full ${botMode === 'ruthless' ? 'bg-amber-500' : 'bg-emerald-500'} animate-pulse`}></div><p className="text-[10px] text-slate-400 font-black uppercase tracking-wider">{botMode === 'ruthless' ? 'Ruthless Mode' : 'Supportive Mode'}</p></div></div>
                </div>
            </div>
            <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar bg-slate-950/30">
                {chatHistory.map((msg) => (
                    <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-slide-up`}>
                        <div className={`flex gap-3 max-w-[90%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 border shadow-sm mt-1 ${msg.role === 'user' ? 'bg-slate-800 border-white/10' : 'bg-indigo-600 border-indigo-500'}`}>{msg.role === 'user' ? <User className="w-4 h-4 text-slate-300" /> : <Bot className="w-4 h-4 text-white" />}</div>
                            <div>
                                <div className={`p-4 text-sm leading-relaxed shadow-lg rounded-2xl ${msg.role === 'user' ? 'bg-slate-800 text-white rounded-tr-none border border-white/5' : 'bg-white/10 backdrop-blur-md text-slate-100 rounded-tl-none border border-white/10'}`}>{msg.content}</div>
                                {msg.suggestedActions && msg.suggestedActions.length > 0 && (<div className="flex flex-wrap gap-2 mt-2">{msg.suggestedActions.map((action, idx) => (<button key={idx} onClick={() => handleActionClick(action)} className="flex items-center gap-1.5 px-3 py-1.5 bg-indigo-500/10 hover:bg-indigo-500/20 border border-indigo-500/20 text-indigo-300 rounded-lg text-[10px] font-bold uppercase tracking-wide transition-all active:scale-95 hover:border-indigo-500/40">{action.actionId.startsWith('navigate_') ? <ChevronRight className="w-3 h-3" /> : <MousePointerClick className="w-3 h-3" />}{action.label}</button>))}</div>)}
                                <span className={`text-[9px] font-bold text-slate-600 mt-1 block ${msg.role === 'user' ? 'text-right' : 'text-left'}`}>{msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                            </div>
                        </div>
                    </div>
                ))}
                {chatLoading && <div className="flex justify-start gap-3 animate-fade-in"><div className="w-8 h-8 rounded-full bg-indigo-600 flex items-center justify-center shrink-0"><Bot className="w-4 h-4 text-white" /></div><div className="bg-white/5 px-5 py-4 rounded-2xl rounded-tl-none flex gap-1.5 items-center border border-white/10"><div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce"></div><div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce delay-100"></div><div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce delay-200"></div></div></div>}
                <div ref={chatEndRef} />
            </div>
            <div className="p-4 bg-slate-900/80 border-t border-white/5 backdrop-blur-xl">
                <form onSubmit={(e) => handleSendMessage(e)} className="relative group">
                    <input type="text" value={chatInput} onChange={(e) => setChatInput(e.target.value)} placeholder="Ask Nova..." className="w-full bg-slate-950 border border-white/10 text-white text-sm rounded-xl pl-4 pr-12 py-4 focus:outline-none focus:border-indigo-500 focus:bg-slate-900 transition-all shadow-inner font-medium" />
                    <button type="submit" disabled={!chatInput.trim() || chatLoading} className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-indigo-600 hover:bg-indigo-500 rounded-lg text-white transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-lg active:scale-95"><Send className="w-4 h-4" /></button>
                </form>
            </div>
        </div>
      </div>
    </div>
  );
};

export default Insights;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Transaction, AIAnalysisResponse, ChatMessage, UserPlan, TransactionType, Budget, BotMode, Category, Goal, FinancialSnapshot, SuggestedAction, GoalProposal, DailyReport, MonthlyReport, ReportType } from '../types';
import { analyzeFinancialData, chatWithFinancialCoach } from '../services/geminiService';
import { generateDailyReport, generateMonthlyReport } from '../services/reportEngine';
import { RefreshCcw, CheckCircle, AlertTriangle, ShieldAlert, Info, TrendingUp, Bot, User, BrainCircuit, Lightbulb, Send, Lock, Sparkles, RefreshCw, Flame, ArrowRight, Zap, Crown, TrendingDown, ShoppingCart, Wallet, Terminal, Activity, MousePointerClick, ChevronRight, Check, X, EyeOff, Target, MessageSquare, AlertOctagon, Calendar, ChevronDown, FileText, BarChart3 } from 'lucide-react';

interface InsightsProps {
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  initialPrompt?: string | null; 
  onPromptHandled?: () => void; 
  onApplyBudgets?: (budgets: Budget[]) => void; 
  insightUsage: number; 
  onIncrementUsage: () => void; 
  botMode: BotMode;
  onNavigate: (tab: string) => void;
  onAddGoal?: (goal: Goal) => void;
  autoScanTriggered?: boolean;
  activeReport?: ReportType;
  spendingLimit?: number;
}

const getIconForType = (type: string) => {
  switch (type) {
    case 'success': return <CheckCircle className="w-5 h-5 text-emerald-400" />;
    case 'warning': return <AlertTriangle className="w-5 h-5 text-amber-400" />;
    case 'critical': return <ShieldAlert className="w-5 h-5 text-rose-400" />;
    default: return <Info className="w-5 h-5 text-blue-400" />;
  }
};

const getColorClass = (type: string) => {
  switch (type) {
    case 'success': return 'bg-emerald-500/10 border-emerald-500/20 text-emerald-100';
    case 'warning': return 'bg-amber-500/10 border-amber-500/20 text-amber-100';
    case 'critical': return 'bg-rose-500/10 border-rose-500/20 text-rose-100';
    default: return 'bg-blue-500/10 border-blue-500/20 text-blue-100';
  }
};

const Insights: React.FC<InsightsProps> = ({ 
    transactions, 
    goals, 
    budgets, 
    userPlan, 
    onUpgradeClick, 
    formatCurrency, 
    initialPrompt, 
    onPromptHandled, 
    onApplyBudgets, 
    insightUsage, 
    onIncrementUsage, 
    botMode, 
    onNavigate, 
    onAddGoal,
    autoScanTriggered = false,
    activeReport,
    spendingLimit = 1000
}) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { 
        id: '1', 
        role: 'assistant', 
        content: botMode === 'ruthless' 
            ? 'System initialized. Ready to audit your spending vectors.' 
            : 'Hello! I\'m ready to help you optimize your financial wellness. What\'s on your mind?', 
        timestamp: new Date(),
        sentiment: 'info'
    }
  ]);
  const [chatLoading, setChatLoading] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState<GoalProposal | null>(null);

  // Dedicated Report State
  const [dailyReport, setDailyReport] = useState<DailyReport | null>(null);
  const [monthlyReport, setMonthlyReport] = useState<MonthlyReport | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isPro = userPlan === 'pro';
  const currentLimit = isUltra ? 1500 : isPro ? 50 : 3;
  const isLocked = insightUsage >= currentLimit;

  // Handle activeReport trigger
  useEffect(() => {
      if (activeReport === 'daily') {
          handleGenerateDaily();
      } else if (activeReport === 'monthly') {
          handleGenerateMonthly();
      } else {
          setDailyReport(null);
          setMonthlyReport(null);
      }
  }, [activeReport, transactions, spendingLimit]);

  const handleGenerateDaily = () => {
      const report = generateDailyReport(transactions, spendingLimit || 1000);
      setDailyReport(report);
      setMonthlyReport(null);
  };

  const handleGenerateMonthly = () => {
      const report = generateMonthlyReport(transactions, spendingLimit || 1000);
      setMonthlyReport(report);
      setDailyReport(null);
  };

  const runAnalysis = async () => {
    if (isLocked || loading) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    // Clear other reports when AI runs to show the Neural Audit results
    setDailyReport(null);
    setMonthlyReport(null);

    try {
      const result = await analyzeFinancialData(transactions, userPlan);
      if (result) setAnalysis(result);
      else setError("Coach is analyzing other portfolios. Try again.");
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (autoScanTriggered && !analysis && !loading && !isLocked) {
        runAnalysis();
    }
  }, [autoScanTriggered, analysis, loading, isLocked]);

  const handleAcceptProposal = (proposal: GoalProposal) => {
      if (proposal.type === 'goal' && onAddGoal) {
          onAddGoal({
              id: Date.now().toString(),
              name: proposal.title,
              targetAmount: proposal.target_amount,
              currentAmount: 0,
              deadline: proposal.deadline || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
              icon: 'star',
              color: 'from-emerald-500 to-teal-500'
          });
      } else if (proposal.type === 'budget' && onApplyBudgets) {
          onApplyBudgets([{
              id: `ai_${Date.now()}`,
              category: (proposal.category as Category) || Category.OTHER,
              limit: proposal.target_amount,
              startDate: new Date().toISOString()
          }]);
      }
      if (analysis) setAnalysis({ ...analysis, goal_proposals: analysis.goal_proposals.filter(p => p.id !== proposal.id) });
  };

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    const now = new Date();
    const currentMonthTxs = transactions.filter(t => new Date(t.date).getMonth() === now.getMonth());
    const income = currentMonthTxs.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const expense = currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

    const catMap: Record<string, number> = {};
    currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const topCat = Object.entries(catMap).sort((a,b) => b[1] - a[1])[0];

    const snapshot: FinancialSnapshot = {
        currentMonthMetrics: {
            income,
            expense,
            savingsRate: income > 0 ? (income - expense) / income : 0,
            topExpenseCategory: topCat ? topCat[0] : 'None'
        },
        recentTransactions: transactions.slice(0, 10),
        activeGoals: goals,
        budgets: budgets
    };

    const response = await chatWithFinancialCoach(userMsg.content, chatHistory, snapshot, botMode, userPlan);
    setChatHistory(prev => [...prev, { 
        id: (Date.now() + 1).toString(), 
        role: 'assistant', 
        content: response.message, 
        timestamp: new Date(),
        sentiment: response.sentiment as any,
        suggestedActions: response.suggestedActions
    }]);
    setChatLoading(false);
  };

  const handleActionClick = (action: SuggestedAction) => {
    if (action.actionId.startsWith('navigate_')) {
        const tab = action.actionId.replace('navigate_', '');
        onNavigate(tab);
    } else if (action.actionId === 'chat_prompt' && action.payload) {
        handleSendMessage(null, action.payload);
    }
  };

  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatHistory, chatLoading]);

  // Daily Report UI
  if (dailyReport) {
      return (
          <div className="h-[calc(100vh-8rem)] flex flex-col items-center justify-center p-4">
              <div className="w-full max-w-2xl bg-slate-950 border border-white/10 rounded-[3rem] p-8 shadow-2xl relative overflow-hidden animate-slide-up">
                  <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/10 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>

                  <div className="flex justify-between items-start mb-8 relative z-10">
                      <div>
                          <div className="flex items-center gap-3 mb-2">
                              <div className="p-2 bg-indigo-600 rounded-xl shadow-lg"><Zap className="w-6 h-6 text-white" /></div>
                              <h2 className="text-2xl font-black text-white uppercase tracking-tighter">Daily Summary</h2>
                          </div>
                          <p className="text-slate-400 text-sm font-medium">{new Date(dailyReport.date).toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
                      </div>
                      <button onClick={() => setDailyReport(null)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X className="w-5 h-5 text-slate-500" /></button>
                  </div>

                  <div className="grid grid-cols-2 gap-6 mb-8">
                      <div className="p-5 bg-slate-900/50 rounded-3xl border border-white/5">
                          <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Risk Level</div>
                          <div className={`text-2xl font-black ${dailyReport.riskLevel === 'Critical' ? 'text-rose-500' : dailyReport.riskLevel === 'Warning' ? 'text-amber-400' : 'text-emerald-400'}`}>
                              {dailyReport.riskLevel} <span className="text-sm text-slate-600 font-bold">({dailyReport.riskScore.toFixed(0)}/100)</span>
                          </div>
                      </div>
                      <div className="p-5 bg-slate-900/50 rounded-3xl border border-white/5">
                          <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Today Spend</div>
                          <div className="text-2xl font-black text-white">
                              {formatCurrency(dailyReport.totals.expense)} <span className="text-sm text-slate-600 font-bold">/ {formatCurrency(dailyReport.totals.budget)}</span>
                          </div>
                      </div>
                  </div>

                  <div className="space-y-4 mb-8">
