const getIconForType = (type: string) => {
  switch (type) {
    case 'success': return <CheckCircle className="w-5 h-5 text-emerald-400" />;
    case 'warning': return <AlertTriangle className="w-5 h-5 text-amber-400" />;
    case 'critical': return <ShieldAlert className="w-5 h-5 text-rose-400" />;
    default: return <Info className="w-5 h-5 text-blue-400" />;
  }
};

const getColorClass = (type: string) => {
  switch (type) {
    case 'success': return 'bg-emerald-500/10 border-emerald-500/20 text-emerald-100';
    case 'warning': return 'bg-amber-500/10 border-amber-500/20 text-amber-100';
    case 'critical': return 'bg-rose-500/10 border-rose-500/20 text-rose-100';
    default: return 'bg-blue-500/10 border-blue-500/20 text-blue-100';
  }
};

const Insights: React.FC<InsightsProps> = ({ 
    transactions, 
    goals, 
    budgets, 
    userPlan, 
    onUpgradeClick, 
    formatCurrency, 
    initialPrompt, 
    onPromptHandled, 
    onApplyBudgets, 
    insightUsage, 
    onIncrementUsage, 
    botMode, 
    onNavigate, 
    onAddGoal,
    autoScanTriggered = false,
    activeReport,
    spendingLimit = 1000
}) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { 
        id: '1', 
        role: 'assistant', 
        content: botMode === 'ruthless' 
            ? 'System initialized. Ready to audit your spending vectors.' 
            : 'Hello! I\'m ready to help you optimize your financial wellness. What\'s on your mind?', 
        timestamp: new Date(),
        sentiment: 'info'
    }
  ]);
  const [chatLoading, setChatLoading] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState<GoalProposal | null>(null);

  // Dedicated Report State
  const [activeView, setActiveView] = useState<'idle' | 'daily' | 'monthly' | 'ai'>('idle');
  const [dailyReport, setDailyReport] = useState<DailyReport | null>(null);
  const [monthlyReport, setMonthlyReport] = useState<MonthlyReport | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isPro = userPlan === 'pro';
  const currentLimit = isUltra ? 1500 : isPro ? 50 : 3;
  const isLocked = insightUsage >= currentLimit;

  // Handle activeReport trigger from external nav
  useEffect(() => {
      if (activeReport === 'daily') {
          handleGenerateDaily();
      } else if (activeReport === 'monthly') {
          handleGenerateMonthly();
      } else if (initialPrompt) {
          // If there's a prompt but no specific report type, just stay in chat or idle
          // but ensure the chat knows to fire
      }
  }, [activeReport, transactions, spendingLimit]);

  // Initial Prompt Handler
  useEffect(() => {
      if (initialPrompt && onPromptHandled) {
          handleSendMessage(null, initialPrompt);
          onPromptHandled();
      }
  }, [initialPrompt]);

  const handleGenerateDaily = () => {
      const report = generateDailyReport(transactions, spendingLimit || 1000);
      setDailyReport(report);
      setActiveView('daily');
  };

  const handleGenerateMonthly = () => {
      const report = generateMonthlyReport(transactions, spendingLimit || 1000);
      setMonthlyReport(report);
      setActiveView('monthly');
  };

  const runAnalysis = async () => {
    if (isLocked || loading) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    setActiveView('ai'); // Switch view immediately to show loading there

    try {
      const result = await analyzeFinancialData(transactions, userPlan);
      if (result) setAnalysis(result);
      else setError("Coach is analyzing other portfolios. Try again.");
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (autoScanTriggered && !analysis && !loading && !isLocked) {
        runAnalysis();
    }
  }, [autoScanTriggered, analysis, loading, isLocked]);

  const handleAcceptProposal = (proposal: GoalProposal) => {
      if (proposal.type === 'goal' && onAddGoal) {
          onAddGoal({
              id: Date.now().toString(),
              name: proposal.title,
              targetAmount: proposal.target_amount,
              currentAmount: 0,
              deadline: proposal.deadline || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
              icon: 'star',
              color: 'from-emerald-500 to-teal-500'
          });
      } else if (proposal.type === 'budget' && onApplyBudgets) {
          onApplyBudgets([{
              id: `ai_${Date.now()}`,
              category: (proposal.category as Category) || Category.OTHER,
              limit: proposal.target_amount,
              startDate: new Date().toISOString()
          }]);
      }
      if (analysis) setAnalysis({ ...analysis, goal_proposals: analysis.goal_proposals.filter(p => p.id !== proposal.id) });
  };

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    const now = new Date();
    const currentMonthTxs = transactions.filter(t => new Date(t.date).getMonth() === now.getMonth());
    const income = currentMonthTxs.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const expense = currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

    const catMap: Record<string, number> = {};
    currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const topCat = Object.entries(catMap).sort((a,b) => b[1] - a[1])[0];

    const snapshot: FinancialSnapshot = {
        currentMonthMetrics: {
            income,
            expense,
            savingsRate: income > 0 ? (income - expense) / income : 0,
            topExpenseCategory: topCat ? topCat[0] : 'None'
        },
        recentTransactions: transactions.slice(0, 10),
        activeGoals: goals,
        budgets: budgets
    };

    const response = await chatWithFinancialCoach(userMsg.content, chatHistory, snapshot, botMode, userPlan);
    setChatHistory(prev => [...prev, { 
        id: (Date.now() + 1).toString(), 
        role: 'assistant', 
        content: response.message, 
        timestamp: new Date(),
        sentiment: response.sentiment as any,
        suggestedActions: response.suggestedActions
    }]);
    setChatLoading(false);
  };

  const handleActionClick = (action: SuggestedAction) => {
    if (action.actionId.startsWith('navigate_')) {
        const tab = action.actionId.replace('navigate_', '');
        onNavigate(tab);
    } else if (action.actionId === 'chat_prompt' && action.payload) {
        handleSendMessage(null, action.payload);
    }
  };

  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatHistory, chatLoading]);

  // --- RENDER HELPERS ---

  const renderDailyReport = () => {
      if (!dailyReport) return null;
      return (
          <div className="space-y-6 animate-slide-up pb-6">
              <div className="flex justify-between items-center">
                  <div className="flex items-center gap-3">
                      <div className="p-2 bg-emerald-500/20 rounded-xl text-emerald-400"><Zap className="w-5 h-5" /></div>
                      <div>
                          <h3 className="text-lg font-black text-white uppercase tracking-tight">Daily Tactical</h3>
                          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">{new Date(dailyReport.date).toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' })}</p>
                      </div>
                  </div>
                  <div className="text-right">
                      <div className={`text-2xl font-black ${dailyReport.riskLevel === 'Critical' ? 'text-rose-500' : dailyReport.riskLevel === 'Warning' ? 'text-amber-400' : 'text-emerald-400'}`}>
                          {dailyReport.riskScore.toFixed(0)} <span className="text-xs text-slate-500">/ 100</span>
                      </div>
                      <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Risk Index</div>
                  </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 bg-slate-900/50 rounded-2xl border border-white/5">
                      <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">24h Burn</div>
                      <div className="text-xl font-black text-white">{formatCurrency(dailyReport.totals.expense)}</div>
                  </div>
                  <div className="p-4 bg-slate-900/50 rounded-2xl border border-white/5">
                      <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Momentum</div>
                      <div className={`text-xl font-black ${dailyReport.metrics.momentumDelta > 0.1 ? 'text-rose-400' : 'text-emerald-400'}`}>
                          {dailyReport.metrics.momentumDelta > 0 ? '+' : ''}{(dailyReport.metrics.momentumDelta * 100).toFixed(0)}%
                      </div>
                  </div>
              </div>

              <div className="space-y-3">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Detected Signals</h4>
                  {dailyReport.signals.map((sig, idx) => (
                      <div key={idx} className="flex gap-3 p-3 bg-slate-900/40 rounded-xl border border-white/5">
                          <div className={`mt-0.5 ${sig.type === 'stable' ? 'text-emerald-400' : 'text-rose-400'}`}>
                              {sig.type === 'stable' ? <CheckCircle className="w-4 h-4" /> : <AlertOctagon className="w-4 h-4" />}
                          </div>
                          <div>
                              <div className="text-xs font-bold text-white">{sig.title}</div>
                              <div className="text-[10px] text-slate-400 leading-relaxed">{sig.description}</div>
                          </div>
                      </div>
                  ))}
              </div>

              <div className={`p-5 rounded-2xl border flex items-start gap-4 ${dailyReport.action.priority === 'high' ? 'bg-rose-500/10 border-rose-500/20' : 'bg-indigo-500/10 border-indigo-500/20'}`}>
                  <div className={`p-2 rounded-lg shrink-0 ${dailyReport.action.priority === 'high' ? 'bg-rose-500 text-white' : 'bg-indigo-500 text-white'}`}>
                      <Target className="w-4 h-4" />
                  </div>
                  <div>
                      <div className="text-[9px] font-black uppercase tracking-widest mb-1 opacity-70">Recommended Action</div>
                      <h4 className="text-sm font-bold text-white mb-1">{dailyReport.action.text}</h4>
                      <div className="text-[10px] opacity-80">Effect: {dailyReport.action.effect}</div>
                  </div>
              </div>
          </div>
      );
  };

  const renderMonthlyReport = () => {
      if (!monthlyReport) return null;
      return (
          <div className="space-y-6 animate-slide-up pb-6">
              <div className="flex justify-between items-center">
                  <div className="flex items-center gap-3">
                      <div className="p-2 bg-amber-500/20 rounded-xl text-amber-400"><Calendar className="w-5 h-5" /></div>
                      <div>
                          <h3 className="text-lg font-black text-white uppercase tracking-tight">Monthly Strategic</h3>
                          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">{monthlyReport.month}</p>
                      </div>
                  </div>
                  <div className="px-3 py-1 bg-white/5 rounded-lg border border-white/10">
                      <span className="text-xs font-bold text-white">{monthlyReport.healthLevel}</span>
                  </div>
              </div>

              <div className="grid grid-cols-3 gap-3">
                  <div className="p-3 bg-slate-900/50 rounded-xl border border-white/5 text-center">
                      <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Health</div>
                      <div className={`text-xl font-black ${monthlyReport.healthScore >= 80 ? 'text-emerald-400' : 'text-amber-400'}`}>{monthlyReport.healthScore.toFixed(0)}</div>
                  </div>
                  <div className="p-3 bg-slate-900/50 rounded-xl border border-white/5 text-center">
                      <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Savings</div>
                      <div className="text-xl font-black text-white">{(monthlyReport.metrics.savingsPowerIndex * 100).toFixed(0)}%</div>
                  </div>
                  <div className="p-3 bg-slate-900/50 rounded-xl border border-white/5 text-center">
                      <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Risk</div>
                      <div className={`text-xl font-black ${monthlyReport.riskScore > 50 ? 'text-rose-500' : 'text-emerald-400'}`}>{monthlyReport.riskScore.toFixed(0)}</div>
                  </div>
              </div>

              <div className="bg-indigo-900/10 border border-indigo-500/20 rounded-2xl p-5 relative overflow-hidden">
                  <div className="absolute top-0 right-0 p-4 opacity-10"><Crown className="w-12 h-12 text-indigo-400" /></div>
                  <h4 className="text-xs font-black text-indigo-300 uppercase tracking-widest mb-3 flex items-center gap-2"><Sparkles className="w-3 h-3" /> Strategic Plan</h4>
                  <div className="text-sm font-bold text-white mb-4">{monthlyReport.strategicPlan.objective}</div>
                  <div className="space-y-2">
                      {monthlyReport.strategicPlan.actions.map((act, i) => (
                          <div key={i} className="flex gap-3 text-xs text-slate-300">
                              <span className="font-bold text-indigo-500">{i+1}.</span>
                              <span>{act}</span>
                          </div>
                      ))}
                  </div>
              </div>

              <div className="space-y-2">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Structural Diagnosis</h4>
                  {monthlyReport.problems.map((prob, idx) => (
                      <div key={idx} className="flex items-center gap-3 p-3 rounded-xl bg-slate-900/30 border border-white/5">
                          <div className={`w-1.5 h-1.5 rounded-full ${prob.severity === 'high' ? 'bg-rose-500' : prob.severity === 'medium' ? 'bg-amber-500' : 'bg-emerald-500'}`}></div>
                          <span className="text-xs font-medium text-slate-300">{prob.title}</span>
                      </div>
                  ))}
              </div>
          </div>
      );
  };

  const renderAiAnalysis = () => {
      if (loading) {
          return (
              <div className="flex flex-col items-center justify-center py-20 space-y-6">
                  <Activity className="w-12 h-12 text-indigo-500 animate-bounce" />
                  <p className="text-slate-400 text-xs font-bold uppercase tracking-[0.3em] animate-pulse">Neural Processing...</p>
              </div>
          );
      }
      if (!analysis) return null;

      return (
          <div className="space-y-6 animate-slide-up pb-6">
              <div className="flex justify-between items-center">
                  <h3 className="text-lg font-black text-white flex items-center gap-2"><BrainCircuit className="w-5 h-5 text-indigo-400" /> Neural Audit</h3>
                  <div className={`px-3 py-1 rounded-lg border text-xs font-bold ${analysis.risk_score > 50 ? 'bg-rose-500/10 border-rose-500/20 text-rose-400' : 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400'}`}>
                      Risk Score: {Math.round(analysis.risk_score)}
                  </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 bg-slate-900/50 rounded-2xl border border-white/5">
                      <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Predicted Burn</div>
                      <div className="text-lg font-black text-white">{formatCurrency(analysis.predicted_spend_next_month)}</div>
                  </div>
                  <div className="p-4 bg-slate-900/50 rounded-2xl border border-white/5 flex items-center justify-center">
                      <TrendingUp className="w-6 h-6 text-indigo-400" />
                  </div>
              </div>

              <div className="space-y-3">
                  {analysis.insights.map((insight, idx) => (
                      <div key={idx} className={`p-4 rounded-xl border flex gap-3 ${getColorClass(insight.type)}`}>
                          <div className="mt-0.5 shrink-0">{getIconForType(insight.type)}</div>
                          <div>
                              <div className="text-xs font-bold mb-0.5">{insight.title}</div>
                              <div className="text-[10px] opacity-90 leading-relaxed">{insight.description}</div>
                          </div>
                      </div>
                  ))}
              </div>

              {analysis.goal_proposals && analysis.goal_proposals.length > 0 && (
                  <div className="bg-gradient-to-br from-indigo-900/20 to-purple-900/10 p-5 rounded-2xl border border-indigo-500/20">
                      <h3 className="text-xs font-black text-indigo-300 uppercase tracking-widest mb-3 flex items-center gap-2"><Sparkles className="w-3 h-3" /> Strategic Proposal</h3>
                      {analysis.goal_proposals.map((proposal) => (
                          <div key={proposal.id} className="space-y-3">
                              <div className="flex justify-between items-start">
                                  <div>
                                      <div className="text-sm font-bold text-white">{proposal.title}</div>
                                      <div className="text-[10px] text-slate-400">{proposal.reason_simple}</div>
                                  </div>
                                  <div className="text-right">
                                      <div className="text-sm font-black text-white">{formatCurrency(proposal.target_amount)}</div>
                                  </div>
                              </div>
                              <div className="flex gap-2">
                                  <button onClick={() => setShowRejectModal(proposal)} className="flex-1 py-2 bg-slate-800 hover:bg-slate-700 text-slate-400 font-bold text-[10px] uppercase tracking-widest rounded-lg transition-colors">Dismiss</button>
                                  <button onClick={() => handleAcceptProposal(proposal)} className="flex-[2] py-2 bg-indigo-600 hover:bg-indigo-500 text-white font-bold text-[10px] uppercase tracking-widest rounded-lg transition-colors shadow-lg">Accept</button>
                              </div>
                          </div>
                      ))}
                  </div>
              )}
          </div>
      );
  };

  return (
    <div className="relative h-[calc(100vh-8rem)]">
      {isLocked && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-950/60 backdrop-blur-xl rounded-[2rem] border border-white/10">
            <div className="text-center p-8 max-w-md animate-slide-up">
                <div className="w-16 h-16 rounded-2xl bg-gradient-to-tr from-indigo-500 to-purple-500 flex items-center justify-center mx-auto mb-6 shadow-2xl"><Lock className="w-8 h-8 text-white" /></div>
                <h2 className="text-2xl font-bold text-white mb-2">Limit Reached</h2>
                <p className="text-slate-400 mb-6 text-sm">Cap of {currentLimit} interactions hit. Upgrade to continue.</p>
                <button onClick={onUpgradeClick} className="w-full py-3 bg-white text-indigo-900 font-bold rounded-xl shadow-xl hover:scale-[1.02] active:scale-95 transition-all">Upgrade Plan</button>
            </div>
        </div>
      )}

      <div className={`grid grid-cols-1 lg:grid-cols-12 gap-6 h-full transition-all duration-500 ${isLocked ? 'blur-md opacity-50 pointer-events-none select-none overflow-hidden' : ''}`}>

        {/* LEFT COLUMN: INTELLIGENCE CORE */}
        <div className="lg:col-span-7 flex flex-col gap-6 overflow-hidden h-full">

            {/* Header Area */}
            <div className="flex items-center justify-between shrink-0">
                <div>
                    <h2 className="text-2xl font-black text-white flex items-center gap-2 tracking-tight">
                        <ScanFace className="w-6 h-6 text-indigo-400" />
                        Command Center
                    </h2>
                    <p className="text-slate-400 text-xs mt-1 font-bold uppercase tracking-widest">Neural Analysis & Reporting</p>
                </div>
                <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest border ${isUltra ? 'bg-indigo-500/10 border-indigo-500/20 text-indigo-400' : 'bg-slate-800 border-white/10 text-slate-400'}`}>
                    Tokens: {insightUsage}/{currentLimit}
                </div>
            </div>

            {/* COMMAND GRID (Buttons) */}
            <div className="grid grid-cols-3 gap-4 shrink-0">
                <button 
                    onClick={runAnalysis} 
                    disabled={loading}
                    className={`flex flex-col items-center justify-center p-4 rounded-2xl border transition-all group active:scale-95 ${activeView === 'ai' ? 'bg-indigo-600/20 border-indigo-500 ring-1 ring-indigo-500/50' : 'bg-slate-900/40 border-white/5 hover:bg-slate-800 hover:border-white/10'}`}
                >
                    <div className={`p-2.5 rounded-xl mb-2 transition-colors ${activeView === 'ai' ? 'bg-indigo-500 text-white' : 'bg-indigo-500/10 text-indigo-400 group-hover:bg-indigo-500 group-hover:text-white'}`}>
                        {loading ? <RefreshCw className="w-5 h-5 animate-spin" /> : <BrainCircuit className="w-5 h-5" />}
                    </div>
                    <span className={`text-[10px] font-black uppercase tracking-widest ${activeView === 'ai' ? 'text-white' : 'text-slate-500 group-hover:text-slate-300'}`}>Neural Audit</span>
                </button>

                <button 
                    onClick={handleGenerateDaily} 
                    className={`flex flex-col items-center justify-center p-4 rounded-2xl border transition-all group active:scale-95 ${activeView === 'daily' ? 'bg-emerald-600/20 border-emerald-500 ring-1 ring-emerald-500/50' : 'bg-slate-900/40 border-white/5 hover:bg-slate-800 hover:border-white/10'}`}
                >
                    <div className={`p-2.5 rounded-xl mb-2 transition-colors ${activeView === 'daily' ? 'bg-emerald-500 text-white' : 'bg-emerald-500/10 text-emerald-400 group-hover:bg-emerald-500 group-hover:text-white'}`}>
                        <Zap className="w-5 h-5" />
                    </div>
                    <span className={`text-[10px] font-black uppercase tracking-widest ${activeView === 'daily' ? 'text-white' : 'text-slate-500 group-hover:text-slate-300'}`}>Daily Tactical</span>
                </button>

                <button 
                    onClick={handleGenerateMonthly} 
                    className={`flex flex-col items-center justify-center p-4 rounded-2xl border transition-all group active:scale-95 ${activeView === 'monthly' ? 'bg-amber-600/20 border-amber-500 ring-1 ring-amber-500/50' : 'bg-slate-900/40 border-white/5 hover:bg-slate-800 hover:border-white/10'}`}
                >
                    <div className={`p-2.5 rounded-xl mb-2 transition-colors ${activeView === 'monthly' ? 'bg-amber-500 text-white' : 'bg-amber-500/10 text-amber-400 group-hover:bg-amber-500 group-hover:text-white'}`}>
                        <Calendar className="w-5 h-5" />
                    </div>
                    <span className={`text-[10px] font-black uppercase tracking-widest ${activeView === 'monthly' ? 'text-white' : 'text-slate-500 group-hover:text-slate-300'}`}>Monthly Strategic</span>
                </button>
            </div>

            {/* CONTENT AREA */}
            <div className="flex-1 bg-slate-950/30 border border-white/5 rounded-[2.5rem] p-6 overflow-y-auto custom-scrollbar relative">
                {activeView === 'idle' && (
                    <div className="h-full flex flex-col items-center justify-center text-center opacity-60">
                        <div className="w-20 h-20 bg-slate-900 rounded-full flex items-center justify-center mb-6 border border-white/5 shadow-xl">
                            <Activity className="w-10 h-10 text-slate-600" />
                        </div>
                        <h3 className="text-xl font-bold text-white mb-2">System Idle</h3>
                        <p className="text-slate-500 text-sm max-w-xs">Select a protocol from the command grid above to initialize analysis.</p>
                    </div>
                )}

                {activeView === 'ai' && renderAiAnalysis()}
                {activeView === 'daily' && renderDailyReport()}
                {activeView === 'monthly' && renderMonthlyReport()}
            </div>
        </div>

        {/* RIGHT COLUMN: COMM LINK */}
        <div className="lg:col-span-5 flex flex-col h-full bg-slate-900/60 border border-white/5 rounded-[2.5rem] overflow-hidden shadow-2xl relative backdrop-blur-xl">
            {/* Header */}
            <div className="p-5 border-b border-white/5 bg-slate-950/50 flex justify-between items-center backdrop-blur-md z-10">
                <div className="flex items-center gap-3">
                    <div className={`w-9 h-9 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${botMode === 'ruthless' ? 'bg-slate-800' : 'bg-gradient-to-tr from-indigo-500 to-purple-500'}`}>
                        {botMode === 'ruthless' ? <Terminal className="w-4 h-4 text-slate-300" /> : <Bot className="w-4 h-4 text-white" />}
                    </div>
                    <div>
                        <h3 className="font-bold text-white text-sm">Financial Agent</h3>
                        <div className="flex items-center gap-1.5 mt-0.5">
                            <div className={`w-1.5 h-1.5 rounded-full ${botMode === 'ruthless' ? 'bg-amber-500' : 'bg-emerald-500'} animate-pulse`}></div>
                            <p className="text-[9px] text-slate-400 font-black uppercase tracking-wider">{botMode === 'ruthless' ? 'Ruthless Mode' : 'Supportive Mode'}</p>
                        </div>
                    </div>
                </div>
            </div>

            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-5 space-y-5 custom-scrollbar">
                {chatHistory.map((msg) => (
                    <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-slide-up`}>
                        <div className={`flex gap-3 max-w-[90%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                            <div className={`w-7 h-7 rounded-lg flex items-center justify-center shrink-0 border shadow-sm mt-1 ${msg.role === 'user' ? 'bg-slate-800 border-white/10' : 'bg-indigo-600 border-indigo-500'}`}>
                                {msg.role === 'user' ? <User className="w-3.5 h-3.5 text-slate-300" /> : <Bot className="w-3.5 h-3.5 text-white" />}
                            </div>
                            <div>
                                <div className={`p-3.5 text-xs leading-relaxed shadow-lg rounded-2xl ${msg.role === 'user' ? 'bg-slate-800 text-white rounded-tr-none border border-white/5' : 'bg-white/5 backdrop-blur-md text-slate-200 rounded-tl-none border border-white/10'}`}>
                                    {msg.content}
                                </div>
                                {msg.suggestedActions && msg.suggestedActions.length > 0 && (
                                    <div className="flex flex-wrap gap-2 mt-2">
                                        {msg.suggestedActions.map((action, idx) => (
                                            <button key={idx} onClick={() => handleActionClick(action)} className="flex items-center gap-1 px-2.5 py-1.5 bg-indigo-500/10 hover:bg-indigo-500/20 border border-indigo-500/20 text-indigo-300 rounded-lg text-[9px] font-bold uppercase tracking-wide transition-all active:scale-95 hover:border-indigo-500/40">
                                                {action.actionId.startsWith('navigate_') ? <ChevronRight className="w-2.5 h-2.5" /> : <MousePointerClick className="w-2.5 h-2.5" />}
                                                {action.label}
                                            </button>
                                        ))}
                                    </div>
                                )}
                                <span className={`text-[8px] font-bold text-slate-600 mt-1 block ${msg.role === 'user' ? 'text-right' : 'text-left'}`}>
                                    {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                </span>
                            </div>
                        </div>
                    </div>
                ))}
                {chatLoading && (
                    <div className="flex justify-start gap-3 animate-fade-in">
                        <div className="w-7 h-7 rounded-lg bg-indigo-600 flex items-center justify-center shrink-0"><Bot className="w-3.5 h-3.5 text-white" /></div>
                        <div className="bg-white/5 px-4 py-3 rounded-2xl rounded-tl-none flex gap-1 items-center border border-white/10">
                            <div className="w-1 h-1 bg-slate-400 rounded-full animate-bounce"></div>
                            <div className="w-1 h-1 bg-slate-400 rounded-full animate-bounce delay-100"></div>
                            <div className="w-1 h-1 bg-slate-400 rounded-full animate-bounce delay-200"></div>
                        </div>
                    </div>
                )}
                <div ref={chatEndRef} />
            </div>

            {/* Input */}
            <div className="p-4 bg-slate-950/80 border-t border-white/5 backdrop-blur-xl">
                <form onSubmit={(e) => handleSendMessage(e)} className="relative group">
                    <input 
                        type="text" 
                        value={chatInput} 
                        onChange={(e) => setChatInput(e.target.value)} 
                        placeholder="Ask Nova..." 
                        className="w-full bg-slate-900 border border-white/10 text-white text-xs rounded-xl pl-4 pr-12 py-3.5 focus:outline-none focus:border-indigo-500 focus:bg-slate-900 transition-all shadow-inner font-medium" 
                    />
                    <button 
                        type="submit" 
                        disabled={!chatInput.trim() || chatLoading} 
                        className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-indigo-600 hover:bg-indigo-500 rounded-lg text-white transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-lg active:scale-95"
                    >
                        <Send className="w-3.5 h-3.5" />
                    </button>
                </form>
            </div>
        </div>
      </div>
    </div>
  );
};

export default Insights;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Account, Budget, Goal, Transaction, UserPlan, ToastMessage, BotMode, Currency, Language, TransactionType, SpendingPeriod, SpendingStatus, ReportType } from '../types';
import { ACCOUNTS, INITIAL_TRANSACTIONS, INITIAL_BUDGETS, INITIAL_GOALS, NAV_ITEMS, TRANSLATIONS } from '../constants';
import { evaluateSpending } from '../services/ruleEngine';
import Dashboard from './Dashboard';
import Transactions from './Transactions';
import Accounts from './Accounts';
import Insights from './Insights';
import Goals from './Goals';
import Plans from './Plans';
import Settings from './Settings';
import ScenarioSandbox from './ScenarioSandbox';
import UpcomingFeatures from './UpcomingFeatures';
import CashflowBeta from './CashflowBeta';
import BillNegotiator from './BillNegotiator';
import LandingPage from './LandingPage';
import OnboardingModal from './OnboardingModal';
import ToastContainer from './Toast';
import FloatingAssistant from './FloatingAssistant';
import Investment from './Investment';
import { Sparkles, LogOut, Zap, ShieldX, Shield, EyeOff } from 'lucide-react';
import SmartMoney from './SmartMoney';

const getMonthlyUsage = (key: string) => {
    try {
        const item = localStorage.getItem(key);
        if (!item) return 0;
        const parsed = JSON.parse(item);
        const now = new Date();
        if (parsed.month !== now.getMonth() || parsed.year !== now.getFullYear()) return 0;
        return parsed.count || 0;
    } catch (e) { return 0; }
};

const safeSetItem = (key: string, value: string) => {
    try { localStorage.setItem(key, value); } catch (e) { console.warn(`Storage quota exceeded for ${key}`); }
};

const PINNABLE_FEATURES = ['budget-monitor', 'sandbox-link', 'goal-tracker', 'system-alerts', 'neural-quota'];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [smartMoneyTab, setSmartMoneyTab] = useState('cashflow');
  const [activeReport, setActiveReport] = useState<ReportType>(null);
  const [isPrivacyMode, setIsPrivacyMode] = useState(() => localStorage.getItem('nova_privacy_mode') === 'true');
  const [isPinMode, setIsPinMode] = useState(false);
  const [autoScanTrigger, setAutoScanTrigger] = useState(false);

  const [onboardingComplete, setOnboardingComplete] = useState(() => localStorage.getItem('nova_onboarding_complete') === 'true');

  const [spendingLimit, setSpendingLimit] = useState<number>(() => {
      const stored = localStorage.getItem('nova_spending_limit');
      if (!stored) return 1000;
      const parsed = parseFloat(stored);
      return Number.isFinite(parsed) && parsed > 0 ? parsed : 1000;
  });

  const [spendingPeriod, setSpendingPeriod] = useState<SpendingPeriod>(() => (localStorage.getItem('nova_spending_period') as SpendingPeriod) || 'monthly');

  const [pinnedIds, setPinnedIds] = useState<string[]>(() => {
    try {
        const saved = localStorage.getItem('nova_pinned_ids');
        return saved ? JSON.parse(saved) : []; 
    } catch { return []; }
  });

  const [featureUsage, setFeatureUsage] = useState<Record<string, number>>(() => {
      try {
          const saved = localStorage.getItem('nova_feature_usage');
          return saved ? JSON.parse(saved) : {};
      } catch { return {}; }
  });

  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');
  const [insightUsage, setInsightUsage] = useState(() => getMonthlyUsage('nova_insight_usage'));
  const [scanUsage, setScanUsage] = useState(() => getMonthlyUsage('nova_scan_usage'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => getMonthlyUsage('nova_negotiation_usage'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [botMode, setBotMode] = useState<BotMode>(() => (localStorage.getItem('nova_bot_mode') as BotMode) || 'ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(() => parseFloat(localStorage.getItem('nova_user_avatar_zoom') || '1'));
  const [userAvatarPos, setUserAvatarPos] = useState(() => {
      try {
          const saved = localStorage.getItem('nova_user_avatar_pos');
          return saved ? JSON.parse(saved) : { x: 0, y: 0 };
      } catch { return { x: 0, y: 0 }; }
  });
  const [userBorder, setUserBorder] = useState(() => localStorage.getItem('nova_user_border') || 'default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');

  const [currency, setCurrency] = useState<Currency>(() => (localStorage.getItem('nova_currency') as Currency) || 'USD');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('nova_language') as Language) || 'en');

  useEffect(() => safeSetItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => safeSetItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => safeSetItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => safeSetItem('nova_goals', JSON.stringify(goals)), [goals]);

  useEffect(() => safeSetItem('nova_user_plan', userPlan), [userPlan]);
  useEffect(() => safeSetItem('nova_currency', currency), [currency]);
  useEffect(() => safeSetItem('nova_language', language), [language]);
  useEffect(() => safeSetItem('nova_bot_mode', botMode), [botMode]);
  useEffect(() => safeSetItem('nova_privacy_mode', isPrivacyMode.toString()), [isPrivacyMode]);
  useEffect(() => safeSetItem('nova_pinned_ids', JSON.stringify(pinnedIds)), [pinnedIds]);
  useEffect(() => safeSetItem('nova_feature_usage', JSON.stringify(featureUsage)), [featureUsage]);
  useEffect(() => safeSetItem('nova_spending_limit', spendingLimit.toString()), [spendingLimit]);
  useEffect(() => safeSetItem('nova_spending_period', spendingPeriod), [spendingPeriod]);
  useEffect(() => safeSetItem('nova_onboarding_complete', onboardingComplete.toString()), [onboardingComplete]);

  useEffect(() => { localStorage.setItem('nova_user_name', userName); }, [userName]);
  useEffect(() => { localStorage.setItem('nova_user_email', userEmail); }, [userEmail]);
  useEffect(() => { if(userAvatar) safeSetItem('nova_user_avatar', userAvatar); }, [userAvatar]);
  useEffect(() => safeSetItem('nova_user_avatar_zoom', userAvatarZoom.toString()), [userAvatarZoom]);
  useEffect(() => safeSetItem('nova_user_avatar_pos', JSON.stringify(userAvatarPos)), [userAvatarPos]);
  useEffect(() => safeSetItem('nova_user_border', userBorder), [userBorder]);
  useEffect(() => safeSetItem('nova_user_bg', userBackground), [userBackground]);

  const spendingStatus: { currentSpend: number; status: SpendingStatus } = useMemo(() => {
      const now = new Date();
      let startDate = new Date();

      if (spendingPeriod === 'weekly') {
          const day = now.getDay();
          const diff = now.getDate() - day;
          startDate = new Date(now.setDate(diff));
          startDate.setHours(0, 0, 0, 0);
      } else {
          startDate = new Date(now.getFullYear(), now.getMonth(), 1);
      }

      const currentSpend = transactions
          .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date) >= startDate)
          .reduce((acc, t) => acc + t.amount, 0);

      const status = evaluateSpending(currentSpend, spendingLimit);
      return { currentSpend, status };
  }, [transactions, spendingPeriod, spendingLimit]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: insightUsage };
      safeSetItem('nova_insight_usage', JSON.stringify(meta));
  }, [insightUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: scanUsage };
      safeSetItem('nova_scan_usage', JSON.stringify(meta));
  }, [scanUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: negotiationUsage };
      safeSetItem('nova_negotiation_usage', JSON.stringify(meta));
  }, [negotiationUsage]);

  const addToast = useCallback((message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), message, type }]);
  }, []);

  const trackFeatureUsage = useCallback((featureId: string) => {
      setFeatureUsage(prev => ({
          ...prev,
          [featureId]: (prev[featureId] || 0) + 1
      }));
  }, []);

  useEffect(() => {
      if (!isLoggedIn) return;
      const hasAutoPinned = localStorage.getItem('nova_has_auto_pinned');
      if (hasAutoPinned) return;

      const totalActions = (Object.values(featureUsage) as number[]).reduce((a, b) => a + b, 0);
      if (totalActions > 10) {
          const sorted = Object.entries(featureUsage)
              .filter(([key]) => PINNABLE_FEATURES.includes(key))
              .sort((a, b) => (b[1] as number) - (a[1] as number))
              .map(([key]) => key)
              .slice(0, 2); 

          if (sorted.length > 0) {
              setPinnedIds(sorted);
              addToast(`System optimization complete. Top ${sorted.length} modules pinned.`, 'info');
              localStorage.setItem('nova_has_auto_pinned', 'true');
          }
      }
  }, [featureUsage, isLoggedIn, addToast]);

  const handleTogglePin = (id: string) => {
    setPinnedIds(prev => {
        if (prev.includes(id)) {
            return prev.filter(p => p !== id);
        }
        const limit = userPlan === 'ultra' ? 5 : userPlan === 'pro' ? 3 : 1;
        if (prev.length >= limit) {
            addToast(`Slot Limit Reached (${limit}). Unpin a module to replace.`, 'error');
            return prev;
        }
        return [...prev, id];
    });
  };

  const handleToggleStealth = useCallback(() => {
    if (userPlan !== 'ultra') {
        addToast('Stealth Protocol is an Elite-exclusive feature.', 'info');
        setActiveTab('plans');
        return;
    }
    setIsPrivacyMode(prev => !prev);
    addToast(`Stealth Protocol ${!isPrivacyMode ? 'Engaged' : 'Disengaged'}`, 'info');
  }, [userPlan, isPrivacyMode, addToast]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        const isModI = (e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'i';
        if (isModI) {
            e.preventDefault();
            setIsPinMode(prev => {
                const newVal = !prev;
                addToast(newVal ? 'Pin Configuration Mode: ACTIVE' : 'Pin Configuration Mode: END', 'info');
                if (newVal) setActiveTab('dashboard');
                return newVal;
            });
        }
        if (e.key === 'Escape' && isPinMode) {
            setIsPinMode(false);
            addToast('Pin Configuration Mode: END', 'info');
        }
        if (e.shiftKey && e.key.toLowerCase() === 'p') {
            handleToggleStealth();
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPinMode, handleToggleStealth, addToast]);

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const formatCurrency = (amount: number) => {
    const safeAmount = isNaN(amount) ? 0 : amount;
    const val = new Intl.NumberFormat(language === 'vi' ? 'vi-VN' : 'en-US', { 
        style: 'currency', currency: currency,
    }).format(safeAmount);

    if (isPrivacyMode && userPlan === 'ultra') {
        return <span className="blur-md opacity-50 bg-white/5 px-1 rounded-md">{val.replace('-', '')}</span>;
    }
    return val;
  };

  const reconcileBalance = (tx: Transaction, direction: 'add' | 'delete') => {
      if (tx.accountId === 'manual') return;
      setAccounts(prev => prev.map(acc => {
          if (acc.id === tx.accountId) {
              const isIncome = tx.type === TransactionType.INCOME;
              let change = tx.amount;
              if (direction === 'add') change = isIncome ? change : -change;
              else change = isIncome ? -change : change;
              return { ...acc, balance: acc.balance + change };
          }
          return acc;
      }));
  };

  const handleAddTransaction = (t: Transaction) => {
      setTransactions(prev => [t, ...prev]);
      reconcileBalance(t, 'add');
      addToast('Transaction recorded.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
      const tx = transactions.find(t => t.id === id);
      if (tx) {
          reconcileBalance(tx, 'delete');
          setTransactions(prev => prev.filter(t => t.id !== id));
          addToast('Transaction purged.', 'info');
      }
  };

  const handleLogin = (name: string) => {
    setIsLoggedIn(true);
    setUserName(name);
    localStorage.setItem('nova_user_name', name);
  };

  const confirmLogout = () => {
    localStorage.removeItem('nova_auth_token');
    setIsLoggedIn(false);
    setIsLogoutModalOpen(false);
  };

  const handleAskCoach = (message?: string) => {
    if (message) {
      setPendingChatQuery(message);
    }
    setActiveTab('insights');
  };

  const handleNavigate = (tab: string, params?: any) => {
    if (params?.autoScan) setAutoScanTrigger(true);
    if (tab === 'smart_money' && params?.tab) {
        setSmartMoneyTab(params.tab);
    }

    // Logic for ReportType navigation
    if (tab !== 'insights') {
        setActiveReport(null);
    } else if (params?.reportType) {
        setActiveReport(params.reportType);
    } else if (tab === 'insights' && !params?.reportType && !pendingChatQuery) {
        setActiveReport(null);
    }

    setActiveTab(tab);
  };

  const handleOnboardingComplete = (name: string, lang: Language, per: SpendingPeriod, lim: number) => {
      const validName = name && name.trim().length > 0 ? name : 'Commander';
      setUserName(validName);
      localStorage.setItem('nova_user_name', validName);

      setLanguage(lang);
      setSpendingPeriod(per);

      const validLimit = Number.isFinite(lim) && lim > 0 ? lim : 1000;
      setSpendingLimit(validLimit);
      localStorage.setItem('nova_spending_limit', validLimit.toString());

      setOnboardingComplete(true);
      addToast(`Welcome, ${validName}. Systems online.`, 'success');
  };

  const handleExportData = () => {
    const data = {
      transactions,
      accounts,
      budgets,
      goals,
      settings: {
        userName, userEmail, userAvatar, userAvatarZoom, userAvatarPos, userBorder, userBackground,
        userPlan, currency, language, botMode, spendingLimit, spendingPeriod
      }
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `nova_backup_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    addToast('Data exported successfully.', 'success');
  };

  const handleImportData = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target?.result as string);
        if (data.transactions) setTransactions(data.transactions);
        if (data.accounts) setAccounts(data.accounts);
        if (data.budgets) setBudgets(data.budgets);
        if (data.goals) setGoals(data.goals);
        if (data.settings) {
            if (data.settings.userName) setUserName(data.settings.userName);
            if (data.settings.userEmail) setUserEmail(data.settings.userEmail);
            if (data.settings.userAvatar) setUserAvatar(data.settings.userAvatar);
            if (data.settings.userPlan) setUserPlan(data.settings.userPlan);
            if (data.settings.currency) setCurrency(data.settings.currency);
            if (data.settings.spendingLimit) setSpendingLimit(data.settings.spendingLimit);
            if (data.settings.spendingPeriod) setSpendingPeriod(data.settings.spendingPeriod);
        }
        addToast('Data imported successfully.', 'success');
      } catch (err) {
        addToast('Invalid backup file.', 'error');
      }
    };
    reader.readAsText(file);
  };

  const handleClearData = () => {
    localStorage.clear();
    window.location.reload();
  };

  const branding = useMemo(() => {
    switch (userPlan) {
      case 'ultra':
        return {
          bg: 'bg-gradient-to-tr from-indigo-600 to-purple-600',
          shadow: 'shadow-indigo-500/40',
          icon: <Sparkles className="w-6 h-6 text-white" />,
          label: 'Elite Terminal'
        };
      case 'pro':
        return {
          bg: 'bg-gradient-to-tr from-amber-400 to-orange-500',
          shadow: 'shadow-amber-500/40',
          icon: <Zap className="w-6 h-6 text-white" />,
          label: 'Pro Uplink'
        };
      default:
        return {
          bg: 'bg-slate-800',
          shadow: 'shadow-black/20',
          icon: <Shield className="w-6 h-6 text-slate-400" />,
          label: 'Free Tier'
        };
    }
  }, [userPlan]);

  if (!isLoggedIn) return <LandingPage onLoginSuccess={handleLogin} />;

  if (!onboardingComplete) return <OnboardingModal onComplete={handleOnboardingComplete} />;

  return (
    <div 
      className={`flex h-screen bg-[#020617] text-slate-100 font-sans selection:bg-indigo-500/30 overflow-hidden relative ${isPinMode ? 'cursor-default' : ''}`}
      style={userBackground ? { backgroundImage: `url(${userBackground})`, backgroundSize: 'cover', backgroundPosition: 'center' } : {}}
    >
      {userBackground && (
          <div className="absolute inset-0 bg-slate-950/50 z-0 pointer-events-none backdrop-blur-[2px]"></div>
      )}

      <FloatingAssistant transactions={transactions} budgets={budgets} userPlan={userPlan} botMode={botMode} isVisible={activeTab !== 'insights'} onOpenChat={handleAskCoach} insightUsage={insightUsage} />

      <aside className="hidden md:flex flex-col w-56 p-4 pb-8 z-20 bg-slate-950/40 backdrop-blur-md border-r border-white/5 relative">
        <div className="flex items-center gap-3 px-4 py-3 mb-8 shrink-0">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${branding.bg} ${branding.shadow}`}>{branding.icon}</div>
            <div className="min-w-0"><h1 className="text-xl font-bold tracking-tight text-white truncate">Nova AI</h1><p className={`text-[10px] font-bold uppercase tracking-wider ${userPlan === 'ultra' ? 'text-purple-400' : userPlan === 'pro' ? 'text-amber-400' : 'text-slate-500'}`}>{branding.label}</p></div>
        </div>
        <nav className="flex-1 space-y-1 overflow-y-auto custom-scrollbar pr-1">
            {NAV_ITEMS.map((item) => {
                const isActive = activeTab === item.id;
                const label = TRANSLATIONS[language]?.[item.id as keyof typeof TRANSLATIONS['en']] || item.label;
                return (
                    <button key={item.id} onClick={() => handleNavigate(item.id)} className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl text-sm font-bold transition-all duration-300 group ${isActive ? 'bg-indigo-600/10 text-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.15)] ring-1 ring-indigo-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>
                        <item.icon className={`w-5 h-5 shrink-0 transition-colors ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-white'}`} />
                        <span className="truncate">{label}</span>
                    </button>
                );
            })}
        </nav>
        <div className="mt-auto pt-6 border-t border-white/5 shrink-0">
             <button onClick={handleToggleStealth} className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all mb-2 ${isPrivacyMode && userPlan === 'ultra' ? 'bg-indigo-500/20 text-indigo-400 border border-indigo-500/30' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}>
                {isPrivacyMode ? <EyeOff className="w-5 h-5 shrink-0" /> : <Shield className="w-5 h-5 shrink-0" />} 
                <span className="truncate">{isPrivacyMode ? 'Stealth Engaged' : 'Stealth Protocol'}</span>
             </button>
             <button onClick={() => setActiveTab('settings')} className="w-full text-left px-3 py-4 rounded-2xl bg-slate-900/50 border border-white/5 flex items-center gap-3 mb-4 hover:bg-slate-800 transition-colors group">
                 <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white overflow-hidden relative border border-white/10 shadow-inner shrink-0">{userAvatar ? <img src={userAvatar} className="w-full h-full object-cover" alt="User" /> : <span className="font-bold text-lg">{userName.charAt(0)}</span>}</div>
                 <div className="overflow-hidden min-w-0"><h4 className="font-bold text-white text-sm truncate group-hover:text-indigo-400 transition-colors">{userName}</h4><p className="text-[10px] text-slate-500 truncate font-bold uppercase tracking-widest">{userPlan} tier</p></div>
             </button>
             <button onClick={() => setIsLogoutModalOpen(true)} className="w-full flex items-center gap-2 px-3 py-2 mb-4 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors uppercase tracking-widest"><LogOut className="w-4 h-4 shrink-0" /> Sign Out</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        {isPinMode && (
          <div className="absolute inset-0 z-[100] bg-black/40 backdrop-blur-[2px] pointer-events-none flex flex-col items-center justify-start pt-20">
              <div className="bg-indigo-600/90 text-white font-black text-xs uppercase tracking-[0.3em] px-8 py-4 rounded-2xl shadow-[0_0_50px_rgba(99,102,241,0.5)] border border-indigo-400/50 animate-pulse pointer-events-auto">
                  Pin Mode Active :: Select Priority Nodes :: Esc to Exit
              </div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
            {activeTab === 'dashboard' && <Dashboard userName={userName} accounts={accounts} transactions={transactions} goals={goals} budgets={budgets} onNavigate={handleNavigate} onAddAccount={() => setActiveTab('accounts')} onAddTransaction={() => setActiveTab('transactions')} onAddGoal={() => setActiveTab('goals')} formatCurrency={formatCurrency} userPlan={userPlan} onAskCoach={handleAskCoach} isPinMode={isPinMode} pinnedIds={pinnedIds} onTogglePin={handleTogglePin} trackEvent={trackFeatureUsage} insightUsage={insightUsage} spendingStatus={spendingStatus.status} currentPeriodSpend={spendingStatus.currentSpend} spendingLimit={spendingLimit} spendingPeriod={spendingPeriod} />}
            {activeTab === 'transactions' && <Transactions transactions={transactions} accounts={accounts} onDelete={handleDeleteTransaction} onAdd={handleAddTransaction} formatCurrency={formatCurrency} onNavigateToAccounts={() => setActiveTab('accounts')} userPlan={userPlan} scanUsage={scanUsage} onIncrementScan={() => setScanUsage(prev => prev + 1)} currency={currency} />}
            {activeTab === 'accounts' && <Accounts accounts={accounts} budgets={budgets} transactions={transactions} userPlan={userPlan} onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account linked.', 'success'); }} onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated.', 'success'); }} onDelete={(id) => { setAccounts(prev => prev.filter(a => a.id !== id)); setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t)); addToast('Account removed.', 'info'); }} formatCurrency={formatCurrency} userName={userName} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} onNavigate={handleNavigate} />}

            {activeTab === 'smart_money' && (
                <SmartMoney 
                    initialTab={smartMoneyTab}
                    transactions={transactions} 
                    accounts={accounts} 
                    goals={goals} 
                    formatCurrency={formatCurrency} 
                    userPlan={userPlan} 
                    onUpgradeClick={() => setActiveTab('plans')} 
                    insightUsage={insightUsage} 
                    onIncrementUsage={(amount) => setInsightUsage(prev => prev + (amount || 1))} 
                    negotiationUsage={negotiationUsage}
                    onIncrementNegotiationUsage={() => setNegotiationUsage(prev => prev + 1)}
                />
            )}

            {activeTab === 'insights' && <Insights transactions={transactions} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} formatCurrency={formatCurrency} insightUsage={insightUsage} onIncrementUsage={() => setInsightUsage(prev => prev + 1)} onApplyBudgets={(newBudgets) => { const existingCats = new Set(budgets.map(b => b.category)); const toAdd = newBudgets.filter(b => !existingCats.has(b.category)); setBudgets(prev => [...prev, ...toAdd]); addToast(`Applied ${toAdd.length} AI limits.`, 'success'); }} initialPrompt={pendingChatQuery} onPromptHandled={() => setPendingChatQuery(null)} botMode={botMode} onNavigate={handleNavigate} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal created from proposal.', 'success'); }} goals={goals} budgets={budgets} autoScanTriggered={autoScanTrigger} activeReport={activeReport} spendingLimit={spendingLimit} />}
            {activeTab === 'goals' && <Goals goals={goals} budgets={budgets} transactions={transactions} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal deployed.', 'success'); }} onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated.', 'success'); }} onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Limit set.', 'success'); }} onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Limit removed.', 'info'); }} formatCurrency={formatCurrency} />}
            {activeTab === 'plans' && <Plans currentPlan={userPlan} onUpgrade={(plan) => { setUserPlan(plan); addToast(`Plan upgraded.`, 'success'); }} onDowngrade={() => { setUserPlan('free'); addToast('Plan reset.', 'info'); }} onNavigateDashboard={() => setActiveTab('dashboard')} />}
            {activeTab === 'investment' && <Investment accounts={accounts} formatCurrency={formatCurrency} userPlan={userPlan} />}
            {activeTab === 'upcoming' && <UpcomingFeatures />}
            {activeTab === 'settings' && <Settings userName={userName} userEmail={userEmail} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} userBackground={userBackground} onUpdateBackground={setUserBackground} userPlan={userPlan} onUpdateProfile={(n, e, a, z, p, b) => { 
                // Immediate manual save to ensure persistence
                localStorage.setItem('nova_user_name', n);
                localStorage.setItem('nova_user_email', e);
                if (a) localStorage.setItem('nova_user_avatar', a);

                setUserName(n); 
                setUserEmail(e); 
                setUserAvatar(a); 
                setUserAvatarZoom(z); 
                setUserAvatarPos(p); 
                setUserBorder(b); 
                addToast('Profile updated.', 'success'); 
            }} addToast={addToast} onExportData={handleExportData} onImportData={handleImportData} onClearData={handleClearData} language={language} onUpdateLanguage={setLanguage} currency={currency} onUpdateCurrency={setCurrency} botMode={botMode} onUpdateBotMode={setBotMode} spendingLimit={spendingLimit} onUpdateSpendingLimit={setSpendingLimit} spendingPeriod={spendingPeriod} onUpdateSpendingPeriod={setSpendingPeriod} />}
        </div>
      </main>

      {isLogoutModalOpen && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-2xl animate-fade-in">
              <div className="bg-[#0f172a] border border-rose-500/30 rounded-[3rem] w-full max-w-sm shadow-[0_0_100px_rgba(244,63,94,0.2)] p-10 text-center animate-slide-up relative">
                  <div className="w-20 h-20 bg-rose-500/20 rounded-[2rem] flex items-center justify-center mx-auto mb-8 border border-rose-500/30"><ShieldX className="w-10 h-10 text-rose-500" /></div>
                  <h3 className="text-2xl font-black text-white mb-3 uppercase tracking-tighter">Terminate?</h3>
                  <div className="space-y-4">
                      <button onClick={confirmLogout} className="w-full py-4 bg-rose-600 hover:bg-rose-500 text-white font-black rounded-2xl shadow-xl transition-all">Sign Out</button>
                      <button onClick={() => setIsLogoutModalOpen(false)} className="w-full py-4 bg-slate-900/50 text-slate-400 font-bold rounded-2xl border border-white/5 hover:text-white transition-all">Stay Connected</button>
                  </div>
              </div>
          </div>
      )}

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Account, Budget, Goal, Transaction, UserPlan, ToastMessage, BotMode, Currency, Language, TransactionType, SpendingPeriod, SpendingStatus, ReportType } from '../types';
import { ACCOUNTS, INITIAL_TRANSACTIONS, INITIAL_BUDGETS, INITIAL_GOALS, NAV_ITEMS, TRANSLATIONS } from '../constants';
import { evaluateSpending } from '../services/ruleEngine';
import Dashboard from './Dashboard';
import Transactions from './Transactions';
import Accounts from './Accounts';
import Insights from './Insights';
import Goals from './Goals';
import Plans from './Plans';
import Settings from './Settings';
import ScenarioSandbox from './ScenarioSandbox';
import UpcomingFeatures from './UpcomingFeatures';
import CashflowBeta from './CashflowBeta';
import BillNegotiator from './BillNegotiator';
import LandingPage from './LandingPage';
import OnboardingModal from './OnboardingModal';
import ToastContainer from './Toast';
import FloatingAssistant from './FloatingAssistant';
import Investment from './Investment';
import { Sparkles, LogOut, Zap, ShieldX, Shield, EyeOff } from 'lucide-react';
import SmartMoney from './SmartMoney';

const getMonthlyUsage = (key: string) => {
    try {
        const item = localStorage.getItem(key);
        if (!item) return 0;
        const parsed = JSON.parse(item);
        const now = new Date();
        if (parsed.month !== now.getMonth() || parsed.year !== now.getFullYear()) return 0;
        return parsed.count || 0;
    } catch (e) { return 0; }
};

const safeSetItem = (key: string, value: string) => {
    try { localStorage.setItem(key, value); } catch (e) { console.warn(`Storage quota exceeded for ${key}`); }
};

const PINNABLE_FEATURES = ['budget-monitor', 'sandbox-link', 'goal-tracker', 'system-alerts', 'neural-quota'];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [smartMoneyTab, setSmartMoneyTab] = useState('cashflow');
  const [activeReport, setActiveReport] = useState<ReportType>(null);
  const [isPrivacyMode, setIsPrivacyMode] = useState(() => localStorage.getItem('nova_privacy_mode') === 'true');
  const [isPinMode, setIsPinMode] = useState(false);
  const [autoScanTrigger, setAutoScanTrigger] = useState(false);

  const [onboardingComplete, setOnboardingComplete] = useState(() => localStorage.getItem('nova_onboarding_complete') === 'true');

  const [spendingLimit, setSpendingLimit] = useState<number>(() => {
      const stored = localStorage.getItem('nova_spending_limit');
      if (!stored) return 1000;
      const parsed = parseFloat(stored);
      return Number.isFinite(parsed) && parsed > 0 ? parsed : 1000;
  });

  const [spendingPeriod, setSpendingPeriod] = useState<SpendingPeriod>(() => (localStorage.getItem('nova_spending_period') as SpendingPeriod) || 'monthly');

  const [pinnedIds, setPinnedIds] = useState<string[]>(() => {
    try {
        const saved = localStorage.getItem('nova_pinned_ids');
        return saved ? JSON.parse(saved) : []; 
    } catch { return []; }
  });

  const [featureUsage, setFeatureUsage] = useState<Record<string, number>>(() => {
      try {
          const saved = localStorage.getItem('nova_feature_usage');
          return saved ? JSON.parse(saved) : {};
      } catch { return {}; }
  });

  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');
  const [insightUsage, setInsightUsage] = useState(() => getMonthlyUsage('nova_insight_usage'));
  const [scanUsage, setScanUsage] = useState(() => getMonthlyUsage('nova_scan_usage'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => getMonthlyUsage('nova_negotiation_usage'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [botMode, setBotMode] = useState<BotMode>(() => (localStorage.getItem('nova_bot_mode') as BotMode) || 'ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(() => parseFloat(localStorage.getItem('nova_user_avatar_zoom') || '1'));
  const [userAvatarPos, setUserAvatarPos] = useState(() => {
      try {
          const saved = localStorage.getItem('nova_user_avatar_pos');
          return saved ? JSON.parse(saved) : { x: 0, y: 0 };
      } catch { return { x: 0, y: 0 }; }
  });
  const [userBorder, setUserBorder] = useState(() => localStorage.getItem('nova_user_border') || 'default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');

  const [currency, setCurrency] = useState<Currency>(() => (localStorage.getItem('nova_currency') as Currency) || 'USD');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('nova_language') as Language) || 'en');

  useEffect(() => safeSetItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => safeSetItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => safeSetItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => safeSetItem('nova_goals', JSON.stringify(goals)), [goals]);

  useEffect(() => safeSetItem('nova_user_plan', userPlan), [userPlan]);
  useEffect(() => safeSetItem('nova_currency', currency), [currency]);
  useEffect(() => safeSetItem('nova_language', language), [language]);
  useEffect(() => safeSetItem('nova_bot_mode', botMode), [botMode]);
  useEffect(() => safeSetItem('nova_privacy_mode', isPrivacyMode.toString()), [isPrivacyMode]);
  useEffect(() => safeSetItem('nova_pinned_ids', JSON.stringify(pinnedIds)), [pinnedIds]);
  useEffect(() => safeSetItem('nova_feature_usage', JSON.stringify(featureUsage)), [featureUsage]);
  useEffect(() => safeSetItem('nova_spending_limit', spendingLimit.toString()), [spendingLimit]);
  useEffect(() => safeSetItem('nova_spending_period', spendingPeriod), [spendingPeriod]);
  useEffect(() => safeSetItem('nova_onboarding_complete', onboardingComplete.toString()), [onboardingComplete]);

  useEffect(() => { localStorage.setItem('nova_user_name', userName); }, [userName]);
  useEffect(() => { localStorage.setItem('nova_user_email', userEmail); }, [userEmail]);
  useEffect(() => { if(userAvatar) safeSetItem('nova_user_avatar', userAvatar); }, [userAvatar]);
  useEffect(() => safeSetItem('nova_user_avatar_zoom', userAvatarZoom.toString()), [userAvatarZoom]);
  useEffect(() => safeSetItem('nova_user_avatar_pos', JSON.stringify(userAvatarPos)), [userAvatarPos]);
  useEffect(() => safeSetItem('nova_user_border', userBorder), [userBorder]);
  useEffect(() => safeSetItem('nova_user_bg', userBackground), [userBackground]);

  const spendingStatus: { currentSpend: number; status: SpendingStatus } = useMemo(() => {
      const now = new Date();
      let startDate = new Date();

      if (spendingPeriod === 'weekly') {
          const day = now.getDay();
          const diff = now.getDate() - day;
          startDate = new Date(now.setDate(diff));
          startDate.setHours(0, 0, 0, 0);
      } else {
          startDate = new Date(now.getFullYear(), now.getMonth(), 1);
      }

      const currentSpend = transactions
          .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date) >= startDate)
          .reduce((acc, t) => acc + t.amount, 0);

      const status = evaluateSpending(currentSpend, spendingLimit);
      return { currentSpend, status };
  }, [transactions, spendingPeriod, spendingLimit]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: insightUsage };
      safeSetItem('nova_insight_usage', JSON.stringify(meta));
  }, [insightUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: scanUsage };
      safeSetItem('nova_scan_usage', JSON.stringify(meta));
  }, [scanUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: negotiationUsage };
      safeSetItem('nova_negotiation_usage', JSON.stringify(meta));
  }, [negotiationUsage]);

  const addToast = useCallback((message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), message, type }]);
  }, []);

  const trackFeatureUsage = useCallback((featureId: string) => {
      setFeatureUsage(prev => ({
          ...prev,
          [featureId]: (prev[featureId] || 0) + 1
      }));
  }, []);

  useEffect(() => {
      if (!isLoggedIn) return;
      const hasAutoPinned = localStorage.getItem('nova_has_auto_pinned');
      if (hasAutoPinned) return;

      const totalActions = (Object.values(featureUsage) as number[]).reduce((a, b) => a + b, 0);
      if (totalActions > 10) {
          const sorted = Object.entries(featureUsage)
              .filter(([key]) => PINNABLE_FEATURES.includes(key))
              .sort((a, b) => (b[1] as number) - (a[1] as number))
              .map(([key]) => key)
              .slice(0, 2); 

          if (sorted.length > 0) {
              setPinnedIds(sorted);
              addToast(`System optimization complete. Top ${sorted.length} modules pinned.`, 'info');
              localStorage.setItem('nova_has_auto_pinned', 'true');
          }
      }
  }, [featureUsage, isLoggedIn, addToast]);

  const handleTogglePin = (id: string) => {
    setPinnedIds(prev => {
        if (prev.includes(id)) {
            return prev.filter(p => p !== id);
        }
        const limit = userPlan === 'ultra' ? 5 : userPlan === 'pro' ? 3 : 1;
        if (prev.length >= limit) {
            addToast(`Slot Limit Reached (${limit}). Unpin a module to replace.`, 'error');
            return prev;
        }
        return [...prev, id];
    });
  };

  const handleToggleStealth = useCallback(() => {
    if (userPlan !== 'ultra') {
        addToast('Stealth Protocol is an Elite-exclusive feature.', 'info');
        setActiveTab('plans');
        return;
    }
    setIsPrivacyMode(prev => !prev);
    addToast(`Stealth Protocol ${!isPrivacyMode ? 'Engaged' : 'Disengaged'}`, 'info');
  }, [userPlan, isPrivacyMode, addToast]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        const isModI = (e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'i';
        if (isModI) {
            e.preventDefault();
            setIsPinMode(prev => {
                const newVal = !prev;
                addToast(newVal ? 'Pin Configuration Mode: ACTIVE' : 'Pin Configuration Mode: END', 'info');
                if (newVal) setActiveTab('dashboard');
                return newVal;
            });
        }
        if (e.key === 'Escape' && isPinMode) {
            setIsPinMode(false);
            addToast('Pin Configuration Mode: END', 'info');
        }
        if (e.shiftKey && e.key.toLowerCase() === 'p') {
            handleToggleStealth();
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPinMode, handleToggleStealth, addToast]);

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const formatCurrency = (amount: number) => {
    const safeAmount = isNaN(amount) ? 0 : amount;
    const val = new Intl.NumberFormat(language === 'vi' ? 'vi-VN' : 'en-US', { 
        style: 'currency', currency: currency,
    }).format(safeAmount);

    if (isPrivacyMode && userPlan === 'ultra') {
        return <span className="blur-md opacity-50 bg-white/5 px-1 rounded-md">{val.replace('-', '')}</span>;
    }
    return val;
  };

  const reconcileBalance = (tx: Transaction, direction: 'add' | 'delete') => {
      if (tx.accountId === 'manual') return;
      setAccounts(prev => prev.map(acc => {
          if (acc.id === tx.accountId) {
              const isIncome = tx.type === TransactionType.INCOME;
              let change = tx.amount;
              if (direction === 'add') change = isIncome ? change : -change;
              else change = isIncome ? -change : change;
              return { ...acc, balance: acc.balance + change };
          }
          return acc;
      }));
  };

  const handleAddTransaction = (t: Transaction) => {
      setTransactions(prev => [t, ...prev]);
      reconcileBalance(t, 'add');
      addToast('Transaction recorded.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
      const tx = transactions.find(t => t.id === id);
      if (tx) {
          reconcileBalance(tx, 'delete');
          setTransactions(prev => prev.filter(t => t.id !== id));
          addToast('Transaction purged.', 'info');
      }
  };

  const handleLogin = (name: string) => {
    setIsLoggedIn(true);
    setUserName(name);
    localStorage.setItem('nova_user_name', name);
  };

  const confirmLogout = () => {
    localStorage.removeItem('nova_auth_token');
    setIsLoggedIn(false);
    setIsLogoutModalOpen(false);
  };

  const handleAskCoach = (message?: string) => {
    if (message) {
      setPendingChatQuery(message);
    }
    setActiveTab('insights');
  };

  const handleNavigate = (tab: string, params?: any) => {
    if (params?.autoScan) setAutoScanTrigger(true);
    if (tab === 'smart_money' && params?.tab) {
        setSmartMoneyTab(params.tab);
    }

    // Logic for ReportType navigation
    if (tab !== 'insights') {
        setActiveReport(null);
    } else if (params?.reportType) {
        setActiveReport(params.reportType);
    } else if (tab === 'insights' && !params?.reportType && !pendingChatQuery) {
        setActiveReport(null);
    }

    setActiveTab(tab);
  };

  const handleOnboardingComplete = (name: string, lang: Language, per: SpendingPeriod, lim: number) => {
      const validName = name && name.trim().length > 0 ? name : 'Commander';
      setUserName(validName);
      localStorage.setItem('nova_user_name', validName);

      setLanguage(lang);
      setSpendingPeriod(per);

      const validLimit = Number.isFinite(lim) && lim > 0 ? lim : 1000;
      setSpendingLimit(validLimit);
      localStorage.setItem('nova_spending_limit', validLimit.toString());

      setOnboardingComplete(true);
      addToast(`Welcome, ${validName}. Systems online.`, 'success');
  };

  const handleExportData = () => {
    const data = {
      transactions,
      accounts,
      budgets,
      goals,
      settings: {
        userName, userEmail, userAvatar, userAvatarZoom, userAvatarPos, userBorder, userBackground,
        userPlan, currency, language, botMode, spendingLimit, spendingPeriod
      }
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `nova_backup_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    addToast('Data exported successfully.', 'success');
  };

  const handleImportData = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target?.result as string);
        if (data.transactions) setTransactions(data.transactions);
        if (data.accounts) setAccounts(data.accounts);
        if (data.budgets) setBudgets(data.budgets);
        if (data.goals) setGoals(data.goals);
        if (data.settings) {
            if (data.settings.userName) setUserName(data.settings.userName);
            if (data.settings.userEmail) setUserEmail(data.settings.userEmail);
            if (data.settings.userAvatar) setUserAvatar(data.settings.userAvatar);
            if (data.settings.userPlan) setUserPlan(data.settings.userPlan);
            if (data.settings.currency) setCurrency(data.settings.currency);
            if (data.settings.spendingLimit) setSpendingLimit(data.settings.spendingLimit);
            if (data.settings.spendingPeriod) setSpendingPeriod(data.settings.spendingPeriod);
        }
        addToast('Data imported successfully.', 'success');
      } catch (err) {
        addToast('Invalid backup file.', 'error');
      }
    };
    reader.readAsText(file);
  };

  const handleClearData = () => {
    localStorage.clear();
    window.location.reload();
  };

  const branding = useMemo(() => {
    switch (userPlan) {
      case 'ultra':
        return {
          bg: 'bg-gradient-to-tr from-indigo-600 to-purple-600',
          shadow: 'shadow-indigo-500/40',
          icon: <Sparkles className="w-6 h-6 text-white" />,
          label: 'Elite Terminal'
        };
      case 'pro':
        return {
          bg: 'bg-gradient-to-tr from-amber-400 to-orange-500',
          shadow: 'shadow-amber-500/40',
          icon: <Zap className="w-6 h-6 text-white" />,
          label: 'Pro Uplink'
        };
      default:
        return {
          bg: 'bg-slate-800',
          shadow: 'shadow-black/20',
          icon: <Shield className="w-6 h-6 text-slate-400" />,
          label: 'Free Tier'
        };
    }
  }, [userPlan]);

  if (!isLoggedIn) return <LandingPage onLoginSuccess={handleLogin} />;

  if (!onboardingComplete) return <OnboardingModal onComplete={handleOnboardingComplete} />;

  return (
    <div 
      className={`flex h-screen bg-[#020617] text-slate-100 font-sans selection:bg-indigo-500/30 overflow-hidden relative ${isPinMode ? 'cursor-default' : ''}`}
      style={userBackground ? { backgroundImage: `url(${userBackground})`, backgroundSize: 'cover', backgroundPosition: 'center' } : {}}
    >
      {userBackground && (
          <div className="absolute inset-0 bg-slate-950/50 z-0 pointer-events-none backdrop-blur-[2px]"></div>
      )}

      <FloatingAssistant transactions={transactions} budgets={budgets} userPlan={userPlan} botMode={botMode} isVisible={activeTab !== 'insights'} onOpenChat={handleAskCoach} insightUsage={insightUsage} />

      <aside className="hidden md:flex flex-col w-56 p-4 pb-8 z-20 bg-slate-950/40 backdrop-blur-md border-r border-white/5 relative">
        <div className="flex items-center gap-3 px-4 py-3 mb-8 shrink-0">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${branding.bg} ${branding.shadow}`}>{branding.icon}</div>
            <div className="min-w-0"><h1 className="text-xl font-bold tracking-tight text-white truncate">Nova AI</h1><p className={`text-[10px] font-bold uppercase tracking-wider ${userPlan === 'ultra' ? 'text-purple-400' : userPlan === 'pro' ? 'text-amber-400' : 'text-slate-500'}`}>{branding.label}</p></div>
        </div>
        <nav className="flex-1 space-y-1 overflow-y-auto custom-scrollbar pr-1">
            {NAV_ITEMS.map((item) => {
                const isActive = activeTab === item.id;
                const label = TRANSLATIONS[language]?.[item.id as keyof typeof TRANSLATIONS['en']] || item.label;
                return (
                    <button key={item.id} onClick={() => handleNavigate(item.id)} className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl text-sm font-bold transition-all duration-300 group ${isActive ? 'bg-indigo-600/10 text-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.15)] ring-1 ring-indigo-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>
                        <item.icon className={`w-5 h-5 shrink-0 transition-colors ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-white'}`} />
                        <span className="truncate">{label}</span>
                    </button>
                );
            })}
        </nav>
        <div className="mt-auto pt-6 border-t border-white/5 shrink-0">
             <button onClick={handleToggleStealth} className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all mb-2 ${isPrivacyMode && userPlan === 'ultra' ? 'bg-indigo-500/20 text-indigo-400 border border-indigo-500/30' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}>
                {isPrivacyMode ? <EyeOff className="w-5 h-5 shrink-0" /> : <Shield className="w-5 h-5 shrink-0" />} 
                <span className="truncate">{isPrivacyMode ? 'Stealth Engaged' : 'Stealth Protocol'}</span>
             </button>
             <button onClick={() => setActiveTab('settings')} className="w-full text-left px-3 py-4 rounded-2xl bg-slate-900/50 border border-white/5 flex items-center gap-3 mb-4 hover:bg-slate-800 transition-colors group">
                 <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white overflow-hidden relative border border-white/10 shadow-inner shrink-0">{userAvatar ? <img src={userAvatar} className="w-full h-full object-cover" alt="User" /> : <span className="font-bold text-lg">{userName.charAt(0)}</span>}</div>
                 <div className="overflow-hidden min-w-0"><h4 className="font-bold text-white text-sm truncate group-hover:text-indigo-400 transition-colors">{userName}</h4><p className="text-[10px] text-slate-500 truncate font-bold uppercase tracking-widest">{userPlan} tier</p></div>
             </button>
             <button onClick={() => setIsLogoutModalOpen(true)} className="w-full flex items-center gap-2 px-3 py-2 mb-4 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors uppercase tracking-widest"><LogOut className="w-4 h-4 shrink-0" /> Sign Out</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        {isPinMode && (
          <div className="absolute inset-0 z-[100] bg-black/40 backdrop-blur-[2px] pointer-events-none flex flex-col items-center justify-start pt-20">
              <div className="bg-indigo-600/90 text-white font-black text-xs uppercase tracking-[0.3em] px-8 py-4 rounded-2xl shadow-[0_0_50px_rgba(99,102,241,0.5)] border border-indigo-400/50 animate-pulse pointer-events-auto">
                  Pin Mode Active :: Select Priority Nodes :: Esc to Exit
              </div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
            {activeTab === 'dashboard' && <Dashboard userName={userName} accounts={accounts} transactions={transactions} goals={goals} budgets={budgets} onNavigate={handleNavigate} onAddAccount={() => setActiveTab('accounts')} onAddTransaction={() => setActiveTab('transactions')} onAddGoal={() => setActiveTab('goals')} formatCurrency={formatCurrency} userPlan={userPlan} onAskCoach={handleAskCoach} isPinMode={isPinMode} pinnedIds={pinnedIds} onTogglePin={handleTogglePin} trackEvent={trackFeatureUsage} insightUsage={insightUsage} spendingStatus={spendingStatus.status} currentPeriodSpend={spendingStatus.currentSpend} spendingLimit={spendingLimit} spendingPeriod={spendingPeriod} />}
            {activeTab === 'transactions' && <Transactions transactions={transactions} accounts={accounts} onDelete={handleDeleteTransaction} onAdd={handleAddTransaction} formatCurrency={formatCurrency} onNavigateToAccounts={() => setActiveTab('accounts')} userPlan={userPlan} scanUsage={scanUsage} onIncrementScan={() => setScanUsage(prev => prev + 1)} currency={currency} />}
            {activeTab === 'accounts' && <Accounts accounts={accounts} budgets={budgets} transactions={transactions} userPlan={userPlan} onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account linked.', 'success'); }} onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated.', 'success'); }} onDelete={(id) => { setAccounts(prev => prev.filter(a => a.id !== id)); setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t)); addToast('Account removed.', 'info'); }} formatCurrency={formatCurrency} userName={userName} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} onNavigate={handleNavigate} />}

            {activeTab === 'smart_money' && (
                <SmartMoney 
                    initialTab={smartMoneyTab}
                    transactions={transactions} 
                    accounts={accounts} 
                    goals={goals} 
                    formatCurrency={formatCurrency} 
                    userPlan={userPlan} 
                    onUpgradeClick={() => setActiveTab('plans')} 
                    insightUsage={insightUsage} 
                    onIncrementUsage={(amount) => setInsightUsage(prev => prev + (amount || 1))} 
                    negotiationUsage={negotiationUsage}
                    onIncrementNegotiationUsage={() => setNegotiationUsage(prev => prev + 1)}
                />
            )}

            {activeTab === 'insights' && <Insights transactions={transactions} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} formatCurrency={formatCurrency} insightUsage={insightUsage} onIncrementUsage={() => setInsightUsage(prev => prev + 1)} onApplyBudgets={(newBudgets) => { const existingCats = new Set(budgets.map(b => b.category)); const toAdd = newBudgets.filter(b => !existingCats.has(b.category)); setBudgets(prev => [...prev, ...toAdd]); addToast(`Applied ${toAdd.length} AI limits.`, 'success'); }} initialPrompt={pendingChatQuery} onPromptHandled={() => setPendingChatQuery(null)} botMode={botMode} onNavigate={handleNavigate} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal created from proposal.', 'success'); }} goals={goals} budgets={budgets} autoScanTriggered={autoScanTrigger} activeReport={activeReport} spendingLimit={spendingLimit} />}
            {activeTab === 'goals' && <Goals goals={goals} budgets={budgets} transactions={transactions} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal deployed.', 'success'); }} onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated.', 'success'); }} onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Limit set.', 'success'); }} onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Limit removed.', 'info'); }} formatCurrency={formatCurrency} />}
            {activeTab === 'plans' && <Plans currentPlan={userPlan} onUpgrade={(plan) => { setUserPlan(plan); addToast(`Plan upgraded.`, 'success'); }} onDowngrade={() => { setUserPlan('free'); addToast('Plan reset.', 'info'); }} onNavigateDashboard={() => setActiveTab('dashboard')} />}
            {activeTab === 'investment' && <Investment accounts={accounts} formatCurrency={formatCurrency} userPlan={userPlan} />}
            {activeTab === 'upcoming' && <UpcomingFeatures />}
            {activeTab === 'settings' && <Settings userName={userName} userEmail={userEmail} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} userBackground={userBackground} onUpdateBackground={setUserBackground} userPlan={userPlan} onUpdateProfile={(n, e, a, z, p, b) => { 
                // Immediate manual save to ensure persistence
                localStorage.setItem('nova_user_name', n);
                localStorage.setItem('nova_user_email', e);
                if (a) localStorage.setItem('nova_user_avatar', a);

                setUserName(n); 
                setUserEmail(e); 
                setUserAvatar(a); 
                setUserAvatarZoom(z); 
                setUserAvatarPos(p); 
                setUserBorder(b); 
                addToast('Profile updated.', 'success'); 
            }} addToast={addToast} onExportData={handleExportData} onImportData={handleImportData} onClearData={handleClearData} language={language} onUpdateLanguage={setLanguage} currency={currency} onUpdateCurrency={setCurrency} botMode={botMode} onUpdateBotMode={setBotMode} spendingLimit={spendingLimit} onUpdateSpendingLimit={setSpendingLimit} spendingPeriod={spendingPeriod} onUpdateSpendingPeriod={setSpendingPeriod} />}
        </div>
      </main>

      {isLogoutModalOpen && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-2xl animate-fade-in">
              <div className="bg-[#0f172a] border border-rose-500/30 rounded-[3rem] w-full max-w-sm shadow-[0_0_100px_rgba(244,63,94,0.2)] p-10 text-center animate-slide-up relative">
                  <div className="w-20 h-20 bg-rose-500/20 rounded-[2rem] flex items-center justify-center mx-auto mb-8 border border-rose-500/30"><ShieldX className="w-10 h-10 text-rose-500" /></div>
                  <h3 className="text-2xl font-black text-white mb-3 uppercase tracking-tighter">Terminate?</h3>
                  <div className="space-y-4">
                      <button onClick={confirmLogout} className="w-full py-4 bg-rose-600 hover:bg-rose-500 text-white font-black rounded-2xl shadow-xl transition-all">Sign Out</button>
                      <button onClick={() => setIsLogoutModalOpen(false)} className="w-full py-4 bg-slate-900/50 text-slate-400 font-bold rounded-2xl border border-white/5 hover:text-white transition-all">Stay Connected</button>
                  </div>
              </div>
          </div>
      )}

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { ComposedChart, Line, Area, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, XAxis, YAxis } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal, Budget, SpendingStatus, SpendingPeriod } from '../types';
import { Flame, Wallet, CreditCard, Target, Zap, Microscope, FileText, ChevronDown, AlignLeft, GitFork, UserCircle, PieChart as PieChartIcon, TrendingUp, AlertCircle, Check, Plus, Rocket, BarChart3, Clock } from 'lucide-react';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string, params?: any) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  isPinMode?: boolean;
  pinnedIds?: string[];
  onTogglePin?: (id: string) => void;
  trackEvent?: (id: string) => void;
  insightUsage?: number;
  spendingStatus?: SpendingStatus;
  currentPeriodSpend?: number;
  spendingLimit?: number;
  spendingPeriod?: SpendingPeriod;
  userName?: string;
}

const COLORS = ['#3b82f6', '#f97316', '#10b981', '#8b5cf6', '#06b6d4', '#ec4899', '#64748b'];

const Dashboard: React.FC<DashboardProps> = ({ 
    accounts, 
    transactions, 
    goals, 
    budgets,
    onNavigate, 
    onAddAccount, 
    onAddTransaction, 
    onAddGoal, 
    formatCurrency, 
    userPlan, 
    onAskCoach, 
    insightUsage = 0,
    spendingStatus,
    currentPeriodSpend = 0,
    spendingLimit = 1000,
    spendingPeriod = 'monthly',
    userName = 'Pilot'
}) => {
  const [spendingComparison, setSpendingComparison] = useState<'year' | 'month'>('year');
  const [activeMenu, setActiveMenu] = useState<string | null>(null);
  const [showScanConfirm, setShowScanConfirm] = useState(false);

  // Close menus on click outside
  useEffect(() => {
      const handleClickOutside = () => setActiveMenu(null);
      document.addEventListener('click', handleClickOutside);
      return () => document.removeEventListener('click', handleClickOutside);
  }, []);

  const toggleMenu = (e: React.MouseEvent, menuId: string) => {
      e.stopPropagation();
      setActiveMenu(activeMenu === menuId ? null : menuId);
  };

  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const dayName = today.toLocaleDateString('en-US', { weekday: 'long' });

  // Capture timestamp on mount/render for "Last Updated"
  const lastUpdated = useMemo(() => new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), []);

  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const creditCardDebt = useMemo(() => {
      return accounts
        .filter(a => a.type === 'Credit Card' && a.balance < 0)
        .reduce((acc, curr) => acc + Math.abs(curr.balance), 0);
  }, [accounts]);

  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const currentDay = today.getDate();
    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);

    return { currentDailyAvg };
  }, [transactions, currentMonth, currentYear]);

  const expenditureData = useMemo(() => {
    const expenses = transactions.filter(t => 
        t.type === TransactionType.EXPENSE && 
        new Date(t.date).getMonth() === currentMonth && 
        new Date(t.date).getFullYear() === currentYear
    );

    const total = expenses.reduce((acc, t) => acc + t.amount, 0);
    const catMap: Record<string, number> = {};

    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const chartData = Object.entries(catMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

    if (chartData.length === 0) {
        return { chartData: [], total: 0, isEmpty: true, topCategory: null };
    }

    return { chartData, total, isEmpty: false, topCategory: chartData[0] };
  }, [transactions, currentMonth, currentYear]);

  const lineChartData = useMemo(() => {
    const daysInCurrentMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const data = [];

    const getDailySpend = (month: number, year: number) => {
        const daily = new Array(32).fill(0);
        transactions.forEach(t => {
            const d = new Date(t.date);
            if (t.type === TransactionType.EXPENSE && d.getMonth() === month && d.getFullYear() === year) {
                daily[d.getDate()] += t.amount;
            }
        });
        for (let i = 1; i < daily.length; i++) daily[i] += daily[i-1];
        return daily;
    };

    const currentMonthData = getDailySpend(currentMonth, currentYear);
    let comparisonData: number[] = [];
    if (spendingComparison === 'year') {
        comparisonData = getDailySpend(currentMonth, currentYear - 1);
    } else {
        let prevMonth = currentMonth - 1;
        let prevYear = currentYear;
        if (prevMonth < 0) { prevMonth = 11; prevYear = currentYear - 1; }
        comparisonData = getDailySpend(prevMonth, prevYear);
    }

    for (let i = 1; i <= daysInCurrentMonth; i++) {
        data.push({
            day: i,
            ThisMonth: currentMonthData[i],
            Comparison: comparisonData[i] 
        });
    }
    return data;
  }, [transactions, currentMonth, currentYear, spendingComparison]);

  const recurringBills = useMemo(() => {
      const subs = transactions.filter(t => t.category === Category.SUBSCRIPTION);
      const unique = new Map();
      subs.forEach(t => {
          if (!unique.has(t.merchant)) unique.set(t.merchant, t);
      });
      return Array.from(unique.values()).slice(0, 5);
  }, [transactions]);

  const recentTransactions = useMemo(() => {
      return transactions.slice(0, 4);
  }, [transactions]);

  const goalMetrics = useMemo(() => {
      const limitVal = Number(spendingLimit);
      const safeLimit = !isNaN(limitVal) && limitVal > 0 ? limitVal : 1;
      const budgetUtilization = (currentPeriodSpend / safeLimit) * 100;

      const budgetProgress = budgets.map(b => {
          const spent = transactions
            .filter(t => t.category === b.category && t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth)
            .reduce((sum, t) => sum + t.amount, 0);
          return { ...b, spent, percentage: Math.min((spent / b.limit) * 100, 100) };
      });

      // Total Savings calculation
      const totalTarget = goals.reduce((acc, g) => acc + g.targetAmount, 0);
      const totalSaved = goals.reduce((acc, g) => acc + g.currentAmount, 0);
      const savingsProgress = totalTarget > 0 ? (totalSaved / totalTarget) * 100 : 0;

      return { budgetUtilization, budgetProgress, totalTarget, totalSaved, savingsProgress };
  }, [currentPeriodSpend, spendingLimit, budgets, transactions, currentMonth, goals]);

  const neuralCapacity = userPlan === 'ultra' ? 1500 : userPlan === 'pro' ? 50 : 3;
  const neuralRemaining = Math.max(0, neuralCapacity - insightUsage);
  const safeName = userName && userName.trim() !== '' ? userName : 'Pilot';
  const displayLimit = spendingLimit && !isNaN(Number(spendingLimit)) ? Number(spendingLimit) : 0;

  const handleProceedWithScan = () => {
    setShowScanConfirm(false);
    onNavigate('insights', { reportType: 'daily' });
  };

  return (
    <div className="h-full overflow-y-auto custom-scrollbar pb-20 px-2 md:px-0">

        {/* Header */}
        <div className="mb-6 mt-2 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div>
                <h1 className="text-2xl md:text-3xl font-black text-white uppercase tracking-tight">Good {dayName}, {safeName}</h1>
                <div className="flex items-center gap-2 mt-1">
                    <span className="flex h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                    <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest">
                        Last Updated: {lastUpdated}
                    </p>
                </div>
            </div>

            {onAddTransaction && (
                <button 
                    onClick={onAddTransaction}
                    className="hidden md:flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 text-white px-5 py-3 rounded-2xl text-xs font-black uppercase tracking-widest shadow-lg shadow-indigo-500/20 active:scale-95 transition-all group"
                >
                    <Plus className="w-4 h-4 group-hover:rotate-90 transition-transform" />
                    <span>Make New Transaction</span>
                </button>
            )}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

            {/* LEFT MAIN PANEL */}
            <div className="lg:col-span-8 flex flex-col gap-6 h-full">

                {/* 1. Spending chart (Previously Expenditure Topology) */}
                <div className="glass-card p-6 md:p-8 rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 backdrop-blur-xl relative overflow-hidden flex flex-col md:flex-row items-center gap-8 min-h-[300px]">
                    <div className="w-48 h-48 md:w-56 md:h-56 relative shrink-0 flex items-center justify-center">
                        {expenditureData.isEmpty ? (
                            <div className="text-center">
                                <div className="w-40 h-40 rounded-full border-2 border-dashed border-indigo-500/30 flex items-center justify-center animate-pulse">
                                    <PieChartIcon className="w-10 h-10 text-indigo-500/50" />
                                </div>
                            </div>
                        ) : (
                            <ResponsiveContainer width="100%" height="100%">
                                <PieChart>
                                    <Pie
                                        data={expenditureData.chartData}
                                        cx="50%"
                                        cy="50%"
                                        innerRadius={60}
                                        outerRadius={90}
                                        paddingAngle={2}
                                        dataKey="value"
                                        stroke="none"
